sessions.push(...[{"number":1,"id":"KpfnldjO3Iw","url":"https://www.youtube.com/watch?v=KpfnldjO3Iw","type":"session","type_he":"סשן","duration":"30:39 דקות","title_he":"מיומנויות הן הקוד החדש","speaker_he":"גיא פודז׳רני · Tessl","summary":"גיא טוען שפיתוח תוכנה עובר ממימוש וקוד אל כוונה והוראות. מיומנויות הם יחידות הקשר לשימוש חוזר, כמו ספריות, ולכן צריך להתייחס אליהם כאל תוכנה: ניתוח סטטי, בדיקות הערכה (בדיקות למיומנויות), בדיקות אבטחה, ניהול תלויות ותצפית בזמן ריצה. הוא מציג גם מחזור חיים חדש לפיתוח הקשר (CDLC).","takeaways":["חמישה כלי איכות מעולם הקוד שחלים על מיומנויות: ניתוח סטטי, בדיקות הערכה כבדיקות, בדיקות אבטחה, ניהול תלויות ותצפית.","מחזור חיים של פיתוח הקשר (CDLC): יוצרים, בודקים, מייעלים, מפיצים, צורכים ומתצפתים.","מעטפת הסוכן שולט במה שהמודל לא מחליט: Intercom ו-OpenAI הובאו כדוגמאות לשליטה כזו.","אבטחה, שימוש חוזר ושיתוף פעולה, ומחזור חיים הם האתגרים בארגון."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. אין פערים בתמלול.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"גיא טוען שפיתוח תוכנה עובר ממימוש וקוד אל כוונה והוראות. מיומנויות הם יחידות הקשר לשימוש חוזר, כמו ספריות, ולכן צריך להתייחס אליהם כאל תוכנה: ניתוח סטטי, בדיקות הערכה (בדיקות למיומנויות), בדיקות אבטחה, ניהול תלויות ותצפית בזמן ריצה. הוא מציג גם מחזור חיים חדש לפיתוח הקשר (CDLC).","chapters":[{"title":"מסגרת: מפיתוח סביב קוד לפיתוח סביב כוונה","body":"גיא פודג'רני, מייסד ומנכ\"ל Tessl, פותח את הכנס ומספר שהחברה הוקמה לפני יותר משנתיים מתוך אמונה שפיתוח תוכנה עובר ממהפכה: מעולם שסובב סביב קוד ומימוש, לעולם שסובב סביב כוונה והוראות. לדבריו, לפני שנתיים זו הייתה טענה שנויה במחלוקת, אבל היום היא כמעט מקובלת על כולם, והדבר המרגש הוא שהמחסנית החדשה של פיתוח תוכנה מתחילה להיבנות לעינינו. הוא מבקש מהמשתתפים לא רק להקשיב אלא לשתף לקחים, כי בניית פרדיגמת פיתוח חדשה היא פעילות קהילתית ולא משימה של ספק אחד.","points":["המהפכה: מפיתוח סביב קוד ומימוש לפיתוח סביב כוונה והוראות","המחסנית החדשה של פיתוח אג'נטי מתחילה להתגבש ואפשר כבר לתאר אותה","בניית פרדיגמה חדשה היא מאמץ קהילתי  -  המשתתפים מוזמנים לשתף לקחים"],"kind":"idea"},{"title":"סקירת המחסנית האג'נטית: חמש שכבות","body":"פודג'רני מציג מבט ראשון על מחסנית התוכנה החדשה. בתחתית נמצאים הפרימיטיבים החדשים  -  המודלים, שהם כוח-העל שקיבלנו. מעליהם כלים, שהופכים מודלים לסוכנים בכך שהם נותנים להם \"ידיים ורגליים\" להשפיע על העולם ולאסוף מידע. מעל אלה יש קונטקסט שמנחה את המודלים, ומעל הכול רתמות (harnesses) שכורכות את המודל ומגבילות אותו. רתמות מתרכבות יחד לקווי ייצור (factory lines) שמשלבים את הכול לצנרת, ומשם למפעלים שלמים. הוא חוזר לתמונה הזו שוב ושוב לאורך ההרצאה.","points":["מודלים ← כלים ← קונטקסט ← רתמות ← קווי ייצור ← מפעלים","כל שכבה מתרכבת על השכבה שמתחתיה","המינוח עוד בתהליך גיבוש  -  \"רתמה\" הוא כרגע המונח הכי מושחת"],"kind":"idea"},{"title":"שכבת הכלים: ידיים ורגליים למודל","body":"כלים הם החלק הכי קל להבנה: יישומי תוכנה שמאפשרים למודל לתקשר עם העולם, להשפיע ולאסוף מידע. אבל פודג'רני מדגיש נקודה עדינה: כלי הוא לעיתים קרובות דרך לעשות דבר בזול יותר, מהר יותר או טוב יותר מאשר למסור אותו למודל  -  לא תמיד רוצים אינטליגנציה גולמית לכל בעיה. הדוגמאות שלו: grep מאפשר לסוכן למצוא מידע בהרבה קבצים ביעילות בלי לטעון את כל הטוקנים, ו-FFmpeg עורך וידאו בצורה הרבה פחות מועדת שגיאות ממה שמודל יעשה. הסוגים הנפוצים הם כלי שורת פקודה (CLI), כלי MCP וקריאות API. כיון שכלים הם תוכנה, הם מתרכבים: אפשר לחבר אותם בצינורות ולכתוב קוד שמרכיב אותם לכלים מותאמים אישית.","points":["כלי = תוכנת שירות שהופכת מודל לסוכן ולעיתים זולה/מהירה/מדויקת יותר מהמודל עצמו","סוגים נפוצים: CLI, כלי MCP, API","כלים מתרכבים  -  אפשר לבנות כלים מותאמים לצורך ספציפי"],"kind":"idea"},{"title":"שכבת הקונטקסט: מה שהמודל לא יודע","body":"השכבה הבאה חדשה לעולם ה-AI. במודלים הכול הוא קונטקסט  -  בסופו של דבר מנהלים מה נכנס לקריאת המודל  -  אבל כשמדברים על קבצי קונטקסט שמפתחים, הם מתמקדים במידע שהסוכן אין לו ולא יכול לדעת, או מידע שהוא יכול להסיק אבל זה בלתי יעיל או מועד שגיאות. פודג'רני מחלק אותו לשלושה סוגים: מדיניות ונהלים (איך הסכמנו להשתמש בפריימוורק, מדיניות האבטחה שלנו, עיצוב ה-API); מפרטים (specs)  -  הגדרות של המוצר שאנחנו בונים או משתמשים בו, במיוחד APIs שמשתנים מהר; ותהליכי עבודה (workflows)  -  איך מטפלים בתקלה, איך עושים סקירת קוד, לפעמים כדי לעזור לסוכן להצליח ולפעמים כי רוצים עקביות וחזרתיות.","points":["קונטקסט = מידע שהסוכן לא יודע או שיקר/מועד שגיאות עבורו להסיק לבד","שלושה סוגים: מדיניות ונהלים, מפרטים, תהליכי עבודה","לפעמים תהליך כתוב נועד לחזרתיות, לא כי הסוכן לא מסוגל"],"kind":"idea"},{"title":"איך טוענים קונטקסט: כללים, סקילס וקונטקסט פסיבי","body":"יש גם מטריצה של איך טוענים קונטקסט. כללים (rules)  -  כמו קובץ CLAUDE.md  -  נדחפים תמיד לחלון הקונטקסט, ולכן צריך לשים לב לגודלם. סקילס נטענים לפי דרישה  -  בין שהמשתמש הפעיל אותם ובין דרך רמזים לסוכן. ויש קונטקסט פסיבי  -  מסמכים כמו architecture.md שסתם זמינים בריפו, ומקווים שהסוכן ימצא אותם בחיפוש אג'נטי. לשם הפשטות פודג'רני מתייחס להמשך לקונטקסט כ\"סקילס\". נקודה חשובה: גם סקילס מתרכבים. סקילס קוראים לכלים (סקילס רבים קיימים כדי להסביר איך להשתמש בכלי), וסקילס קוראים לסקילס אחרים  -  למשל תהליך טיפול בתקלה שקורא לסקיל לאיסוף לוגים מ-Datadog, לסקיל לניתוח שורש הבעיה, ולסקיל שמתעד ב-Jira. הרכבה היא מה שהופך תוכנה לחזקה  -  אי אפשר לכתוב קרנל בכל פעם שרוצים לבנות דף.","points":["כללים נטענים תמיד (שים לב לגודל), סקילס לפי דרישה, מסמכים זמינים פסיבית","סקילס קוראים לכלים וגם לסקילס אחרים  -  דוגמת תהליך טיפול בתקלה","הרכבה (composability) היא מקור הכוח של תוכנה, והיא תקפה גם לסקילס"],"kind":"idea"},{"title":"שכבת הרתמות: דטרמיניזם שעוטף הסתברות","body":"רתמה היא תוכנה דטרמיניסטית שעוטפת מודל הסתברותי  -  Claude Code הוא הדוגמה הידועה. הרתמה שולטת בהרבה: איך טוענים כללים וסקילס, מה מוגדר בקובץ הקונפיגורציה, אילו כלים זמינים, ואילו הגבלות חלות בתוך הקונטיינר. רתמות הופכות לפריימוורקים ניתנים להרחבה: אפשר לכתוב תוספים (plugins) עם כלים וסקילס משלך, ואפשר להגדיר הוקים (hooks)  -  קטעי תוכנה דטרמיניסטיים שרצים בכל פרומפט או בכל קריאת כלי, יכולים לערוך את הפרומפט או לחסום פעולה לגמרי. פודג'רני מביא שתי דוגמאות מהשטח: אינטרקום מתוארת כחוסמת פעולת הסוכן אלא אם הסקיל הרלוונטי נטען  -  \"המודל לא בוחר, זה תמיד ייטען\"; וצוות ב-OpenAI (עם דובר שיופיע בהמשך הכנס) בנה רתמה מותאמת שלא מאפשרת קומיט בלי כיסוי טסטים מסוים.","points":["רתמה = תוכנה דטרמיניסטית סביב מודל הסתברותי; Claude Code הוא דוגמה","הוקים: קוד דטרמיניסטי שרץ על פרומפטים וקריאות כלים  -  יכול לערוך או לחסום","דוגמאות: חסימת פעולה עד טעינת סקיל (Intercom); חסימת קומיט בלי כיסוי טסטים (OpenAI)"],"kind":"idea"},{"title":"מהרתמות לקווי ייצור, ולמה \"הקונטקסט הוא הקוד החדש\"","body":"גם רתמות מתרכבות: אפשר לקחת רתמת מוצר שטובה בפיתוח בקשת פיצ'ר, רתמת קידוד שיודעת לבנות, רתמת אבטחה ורתמת DevOps שיודעת לפרוס  -  ולארוז הכול לקו ייצור שנראה כמו צנרת: בקשת פיצ'ר נכנסת, פיצ'ר שנשלח יוצא. בחזרה למחסנית: הכלים, הרתמות, קווי הייצור והמפעלים  -  כולם תוכנה שעוטפת מודל. אבל יש רק שתי ישויות חישוב חדשות באמת: המודלים עצמם, והקונטקסט שהוא יליד המודלים  -  הוא ממש נכנס למטריצות ומשנה את מה שקורה. מסקנת פודג'רני: הרבה מהשכבות הן פריימוורקים, אבל הקונטקסט הוא הקוד החדש  -  המקום שבו באמת מתכנתים את המודל.","points":["רתמות מתרכבות לקווי ייצור: קלט חוזר נכנס, תוצר מוכן יוצא","הכלים והרתמות הם תוכנה; שתי ישויות החישוב החדשות הן המודלים והקונטקסט","התזה: הקונטקסט הוא הקוד החדש  -  שם מתכנתים את המודל"],"kind":"idea"},{"title":"סקילס כספריות: הספקטרום מפרומפט לסקיל ופיצוץ הסקילס","body":"הקונטקסט שאנחנו כותבים נע על ספקטרום: פרומפטים חד-פעמיים בסשן אינטראקטיבי, דרך מסמכים ששוכנים לצד הקוד, כללים פרויקטיים שחוזרים בין פרויקטים, ועד סקילס  -  שתוכננו מראש לשימוש חוזר, ממש כמו ספריות. אם עושים משהו פעם אחת, כותבים פרומפט; אם חוזרים עליו, הופכים אותו לסקיל. השימוש החוזר הוא אמצעי לסקיילינג, ולכן רואים פיצוץ: לפי ניתוח שערך עם GitHub, יש כבר כשני מיליון סקילס ב-GitHub, מקום מאפס בתחילת השנה  -  בחלקם באיכות גבוהה ובחלקם לא. בארגונים, לדבריו, אין לו מספרים אבל רואים מגמת פיצוץ דומה. את התחושה הארגונית הוא ממחיש במם של ג'ון טרבולטה המבולבל: לארגונים יש סקילס, הם מתרבים, והם מאבדים שליטה.","points":["ספקטרום: פרומפט → מסמכים → כללים → סקילס (ספרייה רב-שימושית)","לפי ניתוח משותף עם GitHub שהציג הדובר: כ-2 מיליון סקילס ב-GitHub, מכמעט אפס בתחילת השנה","גם בארגונים פיצוץ דומה  -  ותחושת אובדן שליטה (מם טרבולטה)"],"kind":"idea"},{"title":"שלושה דליי אתגרים: אבטחה וממשל, שימוש חוזר, מחזור חיים","body":"האתגר הראשון הוא אבטחה. סקילס מבוצעים על ידי הסוכן ויכולים להיות זדוניים: לדבריו, באקו-סיסטם פתוח אחד נראו מעל 30% סקילס זדוניים  -  דרך קלה מאוד לפרוץ פנימה. יש גם \"סקילס רשלניים\" שדורשים מהסוכן פעולה בלי הוראות בטיחות (למשל \"עדכן את הטבלה\" בלי שורת \"אל תמחק את הטבלה\"), ו\"סקילס פגיעים\" שמנחים לשים טוקנים וסודות במקומות גלויים בלוגים. אם יש סיכון, נדרש ממשל: לדעת אילו סקילס בשימוש, מי משתמש במה, ואם סקיל נפרץ  -  לגלות את זה. הדלי השני הוא שימוש חוזר ושיתוף פעולה: הוא מספר על חברת יוניקורן עם אלף מפתחים שבה כולם כתבו את אותם סקילס שוב ושוב, הקימו ריפו משותף  -  והוא קרס: אי אפשר לדעת איזה מהשבעה סקילס הזהים טוב, \"עובד אצלי על המכונה\" בין סוכנים שונים, ו-PRים לסקילס שלא ברור אם משפרים או פוגעים. אף אחד לא סמך על כלום, וכולם חזרו לכתוב לבד. הדלי השלישי הוא מחזור חיים: תוכנה מסריחה, וגם סקילס  -  המודלים משתנים, ה-APIs משתנים, וסקיל מצוין שלא מתוחזק הופך מזיק. אבל יש גם גזר: עם סוכנים אפשר להפוך תחזוקה לאופטימיזציה  -  לצפות בלוגים וב-PRים ולהפוך תצפיות לשיפורים אוטומטיים של סקילס.","points":["אבטחה: סקילס זדוניים (>30% באקו-סיסטם פתוח אחד, לדברי הדובר), רשלניים ופגיעים","ממשל: לדעת מה מותקן, מי משתמש, ומתי משהו נפרץ","שיתוף פעולה בלי בקרת איכות קורס  -  סיפור הריפו המשותף של היוניקורן","סקילס מסריחים כמו תוכנה; תחזוקה מונעת נזק ותצפיות מאפשרות אופטימיזציה"],"kind":"idea"},{"title":"חמש דיסציפלינות תוכנה מיושמות על סקילס","body":"החדשות הטובות: הבעיות מוכרות מעולם הקוד, ויש להן פתרונות מוכרים. ראשית, ניתוח סטטי  -  לבדוק סקיל בלי להריץ: לינטינג לשדות ומבנה, בדיקות איכות ואבטחה, וריוויו אג'נטי מול פרקטיקות מומלצות (ב-Tessl הם בונים lint ו-review שבודקים מול השיטות של Anthropic, למשל גילוי הדרגתי ותמציתיות). שנית, טסטים  -  המקבילה בסקילס היא איבאלואציות (evals): מגדירים סביבה, מריצים סוכן דרך משימה ושופטים את התוצאה. יש רמות: איבאל של סקיל בודד (כמו טסט יחידה), איבאל של פרויקט עם עשרים סקילס (כמו טסט אינטגרציה  -  למשל להפיק תרחיש מ-PR ישן), ואיבאל מקיף להשוואת מודלים (כמו טסט קצה-לקצה  -  למשל אם מודל זול מספיק טוב למשימה; שמות הדגמים בדוגמה שלו עולו מעורפלים בתמלול). וכמו בטסטים, איכות התרחיש קריטית  -  תרחיש גרוע הוא בזבוז טוקנים. שלישית, אבטחה: סריקה סטטית של סקילס (Snyk ואחרים כבר הכניסו סריקת סקילס; ב-Tessl שילבו את Snyk ברג'יסטרי), תחום מתהווה של רד-טימינג דינמי, ואבטחת שרשרת אספקה. רביעית, ניהול תלויות: תלויות הן כאב מוכר  -  מתנתקות, מתנגשות, מסריחות או נפרצות  -  ולכן צריך מנהל חבילות לסקילס: רג'יסטרי לגילוי, ניהול גרסאות עם יכולת תיקון והחזרה, זיכרון של מה הותקן, שערי איכות ואבטחה, ותאימות בין סוכנים שונים כמו ש-npm לא איכפת באיזו מערכת הפעלה אתה. חמישית, תצפיתיות: בסוף יוצאים מהמעבדה  -  עוקבים אחרי סוכנים בזמן ריצה, מפיקים מהם תרחישי איבאל אמיתיים, וכורים מהצלחות וכישלונות הזדמנויות לסקילס חדשים או למחיקה.","points":["ניתוח סטטי: לינטינג, מדדי איכות ואבטחה, ריוויו אג'נטי מול פרקטיקות","איבאלואציות = הטסטים של סקילס: רמת סקיל, רמת פרויקט, השוואת מודלים; איכות התרחיש קריטית","אבטחה: סריקה סטטית, רד-טימינג דינמי, שרשרת אספקה","ניהול תלויות: רג'יסטרי, גרסאות, זיכרון התקנות, תאימות בין סוכנים","תצפיתיות: ניטור סוכנים בזמן ריצה → תרחישי איבאל וכריית פערים"],"kind":"idea"},{"title":"מחזור חיי פיתוח קונטקסט (CDLC), סיכום והכרזת Tessl Agent","body":"כשמחברים את כל הכלים, מתקבל מחזור חיים שלם  -  אבל פודג'רני מדגיש: לא SDLC אלא CDLC, מחזור חיי פיתוח קונטקסט. בני אדם צריכים לחיות בתוכו ולהשאיר את ה-SDLC לסוכנים: מייצרים קונטקסט, מעריכים ובודקים אותו, ממטבים, מפיצים דרך ניהול חבילות, צורכים בצורה מאובטחת, צופים במה שקרה  -  ושוב ושוב. בסיכום: יש מחסנית תוכנה חדשה לפיתוח אג'נטי  -  מודלים כמו מערכות הפעלה, כלים כיישומים, קונטקסט כקוד חדש, רתמות כפריימוורקים (שיותר ויותר ארגונים יתאימו אישית או יבנו), וקווי ייצור כצנרת. סקילס הם הקוד החדש וצריך להתייחס אליהם ככה ולתת להם את הכלים הנכונים. לסיום הוא מכריז על גרסה ראשונית של Tessl Agent  -  סוכן ורטיקלי שעוזר לפתח קונטקסט, רתמות, קווי ייצור ומפעלים, מקומית, בצנרת או ממרכז הבקרה של Tessl  -  ומזמין להירשם לגישה מוקדמת בדוכן או באתר.","points":["CDLC: בני אדם חיים במחזור חיי הקונטקסט; סוכנים עושים את ה-SDLC","מחזור: ייצור → הערכה ובדיקה → אופטימיזציה → הפצה → צריכה מאובטחת → תצפית → חזרה","הכרזה: Tessl Agent  -  סוכן ורטיקלי לפיתוח קונטקסט ורתמות, בגישה מוקדמת"],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["יש מחסנית תוכנה חדשה לפיתוח אג'נטי: מודלים, כלים, קונטקסט, רתמות, קווי ייצור ומפעלים  -  וכל שכבה מתרכבת על קודמתה.","הקונטקסט הוא הקוד החדש: סקילס הם ספריות של ידע והוראות, ויש להתייחס אליהם ברצינות שמייחסים לקוד.","אתגרי הסקילס (אבטחה, ממשל, שיתוף פעולה, ריקבון) הם בעיות קוד קלאסיות  -  והפתרונות המוכרים עובדים: ניתוח סטטי, איבאלואציות, אבטחה, ניהול תלויות ותצפיתיות.","בני אדם צריכים לעבור לחיות במחזור חיי פיתוח קונטקסט (CDLC) ולהשאיר את ה-SDLC לסוכנים."],"kind":"idea"}],"diagram":{"title":"המחסנית האג'נטית של פודג'רני: מודלים עד מפעלים, עם לולאת ה-CDLC","structure":"מחסנית שכבות אנכית שבה כל שכבה מתרכבת על זו שמתחתיה, ומעליה חצים מעגליים של מחזור חיי פיתוח הקונטקסט.","nodes":[{"id":"models","label":"מודלים (פרימיטיבים  -  \"מערכת ההפעלה\")"},{"id":"tools","label":"כלים (יישומים: CLI, MCP, API)"},{"id":"context","label":"קונטקסט / סקילס (הקוד החדש: כללים, מפרטים, תהליכים)"},{"id":"harness","label":"רתמות (פריימוורקים דטרמיניסטיים + הוקים)"},{"id":"line","label":"קווי ייצור (צנרת: בקשת פיצ'ר → פיצ'ר שנשלח)"},{"id":"factory","label":"מפעלים (תהליכי פיתוח שלמים)"},{"id":"cdlc","label":"CDLC: ייצור → הערכה → אופטימיזציה → הפצה → צריכה מאובטחת → תצפית → חזרה"}],"edges":[{"from":"tools","to":"models","label":"קוראים ומפעילים"},{"from":"context","to":"tools","label":"מנחה את הכלים ומוזן ישירות למודל"},{"from":"harness","to":"context","label":"טוען, מגביל ומחייב (הוקים)"},{"from":"line","to":"harness","label":"מרכיב רתמות לצנרת"},{"from":"factory","to":"line","label":"מרכיב קווים לתהליך מלא"},{"from":"cdlc","to":"context","label":"האדם מנהל את הקונטקסט במחזוריות"}]},"terms":[{"term":"פיתוח אג'נטי (Agentic Development)","definition":"סגנון פיתוח שבו סוכנים מבוססי מודלים מבצעים חלקים גדולים מעבודת הפיתוח, והאדם מנחה בכוונה ובהוראות."},{"term":"רתמה (Harness)","definition":"תוכנה דטרמיניסטית שעוטפת מודל הסתברותי ושולטת באינטראקציה איתו: מה נטען לקונטקסט, אילו כלים זמינים ומה מותר."},{"term":"קו ייצור (Factory line)","definition":"צנרת המרכיבה מספר רתמות יחד  -  קלט חוזר (למשל בקשת פיצ'ר) נכנס ותוצר מוכן (פיצ'ר שנשלח) יוצא."},{"term":"כלי (Tool)","definition":"רכיב תוכנה שהסוכן מפעיל כדי לבצע פעולה או לאסוף מידע  -  למשל grep, FFmpeg, MCP או API."},{"term":"MCP","definition":"פרוטוקול שדרכו הסוכן מפעיל כלים ישירות; הוזכר כאחד הסוגים הנפוצים של כלים."},{"term":"מדיניות ונהלים (Policies & practices)","definition":"הסכמים ארגוניים שמתועדים כדי ליידע את הסוכן: איך משתמשים בפריימוורק, מה מדיניות האבטחה, איך מעצבים API."},{"term":"מפרט (Spec)","definition":"הגדרת מוצר  -  מידע על מה שבונים או משתמשים בו, שחוסך מהסוכן ניסוי וטעיה יקר."},{"term":"תהליך עבודה (Workflow)","definition":"הוראות צעד-אחר-צעד איך לבצע משימה חוזרת, למשל טיפול בתקלה או סקירת קוד."},{"term":"כללים (Rules)","definition":"קונטקסט שתמיד נטען לחלון הקונטקסט של המודל, כמו קובץ CLAUDE.md."},{"term":"סקיל (Skill)","definition":"יחידת קונטקסט הנטענת לפי דרישה  -  בהפעלה ידנית או דרך רמזים לסוכן; מעין ספרייה קלת-משקל של ידע והוראות."},{"term":"קונטקסט פסיבי","definition":"מסמכים זמינים בריפו (למשל architecture.md) שהסוכן אמור למצוא בחיפוש לבד."},{"term":"הוק (Hook)","definition":"קטע תוכנה דטרמיניסטי ברתמה שרץ בכל פרומפט או קריאת כלי ויכול לערוך או לחסום אותו."},{"term":"תוסף (Plugin)","definition":"הרחבה לרתמה שמכניסה כלים וסקילס משל הארגון."},{"term":"שימושיות חוזרת (Reusability)","definition":"התכונה שהופכת סקיל לספרייה: נכתב פעם אחת ומשמש שוב ושוב, ולכן משתלם להשקיע בו."},{"term":"סקיל זדוני","definition":"סקיל שנבנה כדי לגרום נזק; לדברי הדובר נצפו בשיעור גבוה באקו-סיסטם פתוח."},{"term":"סקיל רשלני","definition":"סקיל שדורש פעולות מסוכנות בלי הוראות בטיחות  -  למשל עדכון טבלה בלי אזהרת מחיקה."},{"term":"סקיל פגיע","definition":"סקיל שמנחה לחשוף מידע רגיש, למשל טוקנים בלוגים."},{"term":"ניתוח סטטי (Static analysis)","definition":"בדיקת סקיל בלי להריצו  -  שדות, מבנה, איכות ואבטחה; מקל אחיד להרבה שינויים."},{"term":"איבאלואציה (Eval)","definition":"המקבילה של טסט לסקיל: מריצים סוכן דרך משימה בסביבה מוגדרת ושופטים את התוצאה."},{"term":"ציון איכות (Quality score)","definition":"צבירה של ניתוח סטטי ודינמי לציון שמסמן איזה סקיל טוב יותר  -  לא מושלם אבל שימושי כיוונית."},{"term":"תצפיתיות (Observability)","definition":"ניטור סוכנים בזמן ריצה כדי לשפר סקילס: הפקת תרחישי איבאל אמיתיים וכריית פערים."},{"term":"מחזור חיי פיתוח קונטקסט (CDLC)","definition":"מחזור העבודה של האדם בעולם אג'נטי: לייצר, להעריך, למטב, להפיץ, לאבטח, לצרוך ולצפות בקונטקסט שוב ושוב."}],"gaps":["ההרצאה מסתיימת בהודיה ובקריאה לשתף לקחים; אין מקטע שאלות ותשובות בתמלול. אחרי הדובר נשמעת העברת מיקרופון של מנחה הכנס (בדיחה על \"compacting\" והכרזות על ההפסקה)  -  לא חלק מהתוכן של פודג'רני. שמות דגמים בדוגמת איבאל המודלים (למשל \"gln5 or q26\") עולו מעורפלים בתמלול האוטומטי ולא ניתן לאמתם; כמו כן אזכור \"ג'ון טרבולטה\" מתייחס ככל הנראה למם מסך, ומשפט \"התלויות הן כיף\" מוצג כבדיחה שלא נאמרה באמת. הנתון על ~2 מיליון סקילס ב-GitHub ועל >30% סקילס זדוניים מיוחס לדובר ולניתוח שהציג, ולא אומת מקור חיצוני."],"source_refs":["https://www.youtube.com/watch?v=KpfnldjO3Iw"]},{"number":2,"id":"ACL7_EsfIio","url":"https://www.youtube.com/watch?v=ACL7_EsfIio","type":"session","type_he":"סשן","duration":"29:07 דקות","title_he":"הפרעה דו-קוטבית, חוסר ויסות ובינה מלאכותית","speaker_he":"דייב קר","summary":"דייב קר משתף מניסיונו האישי עם הפרעה דו־קוטבית, ומחבר בין קשב, שינה, קצב עבודה והשימוש בכלי בינה מלאכותית. זו הרצאה אישית על ויסות ועל גבולות, לא מדריך לאבחון או טיפול.","takeaways":["הדובר מתאר כיצד שינה, קצב יום וסביבה תומכת משפיעים על עבודתו.","המשוב המיידי מכלי AI עלול, מניסיונו, לעודד עבודה ללא הפסקה ולהעמיס על הקשב.","הוא מציע לעצור, לבקש תשובות קצרות ולשמור קשר עם אנשים שמכירים אותו.","כשקוד נוצר במהירות, צריך לשמור הבנה משותפת של המערכת ולא לאבד את המודל המנטלי שלה."],"category":"אנשים וקשב","coverage":"כל התמליל הזמין נסקר. הסיום נחתך באמצע שאלות ותשובות. הסיפור אישי ואינו ייעוץ רפואי.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"דייב קר משתף מניסיונו האישי עם הפרעה דו־קוטבית, ומחבר בין קשב, שינה, קצב עבודה והשימוש בכלי בינה מלאכותית. זו הרצאה אישית על ויסות ועל גבולות, לא מדריך לאבחון או טיפול.","chapters":[{"title":"פתיחה ודיסקליימר: לדבר באותנטיות על בריאות נפש","body":"דייב קר מספר שהוגשה להצעה להרצות בכנס ברגע האחרון, ובחר נושא שחי איתו: הפרעה דו-קוטבית, מה שהחיים איתה חייבו אותו ללמוד, והמושגים רגולטורים ודיסרגולטורים  -  דברים שיכולים לשנות את המצב הפיזי או הנפשי. הוא מקדים דיסקליימר: בריאות נפש היא נושא מורכב, להיות נחמדים אחד לשני כי לא יודעים מה אנשים עוברים, להיות נחמדים לעצמכם, ואם יש ספק  -  לפנות לאיש מקצוע רפואי.","points":["ההרצאה אישית: על החיים עם הפרעה דו-קוטבית ועל רגולציה","דיסקליימר בריאות נפש: להיות נחמדים, ולפנות לאיש מקצוע כשצריך"],"kind":"idea"},{"title":"מהי באמת הפרעה דו-קוטבית","body":"קר מספר שכשאובחן לא הסכים עם האבחנה כי חשב שדו-קוטבי זה \"קצת למעלה, קצת למטה\"  -  אבל החוויה שלו הייתה מורכבת וכאוטית הרבה יותר. הוא למד שהמצבים יכולים להיות קיצוניים: היפומאניה (אנרגיה גבוהה, מעט שינה, דיבור בלחץ), מאניה (תקופות ממושכות של התנהגות אימפולסיבית ומזיקה) ועד פסיכוזה בקצה; ובצד הנמוך  -  דיכאון הדומה לדיכאון חד-קוטבי או עמיד לטיפול. הוא מסביר את ההבדל בין טיפוס 2 (דיכאון ממושך עם עליות להיפומאניה) לטיפוס 1 (תקופות מאניה או פסיכוזה ארוכות), ואתגר מרכזי: מי שמנהל את המחלה היטב נראה \"בסדר\"  -  אבל יכול להחלים מאוד. לפי מה שהוא מציג מהמחקר: המחלה תורשתית מאוד (כ-70%), פוגעת ברגולציה של מערכת הלימבית, ברגישות דופמינרגית ובביולוגיה צירקדית, ויש תופעת \"קינדלינג\": כל אפיזודה פוגעת במסלולים העצביים, ולכן דו-קוטבי לא מטופל הוא מחלה ניוונית. הוא מהסס לצטט את המספרים אבל עושה זאת כדי לתת צדק למציאות: לדבריו אחד משלושה עם הפרעה דו-קוטבית ינסה התאבדות, ובלי טיפול אחד מחמישה ישלים התאבדות.","points":["דו-קוטבי הוא לא \"קצת למעלה קצת למטה\" אלא מצבים קיצוניים וכאוטיים","היפומאניה, מאניה ופסיכוזה מול דיכאון קשה; הבדל בין טיפוס 1 לטיפוס 2","לפי הדובר: ~70% תורשתיות; \"קינדלינג\"  -  כל אפיזודה מנוונת; סיכון התאבדותי גבוה מאוד בלי טיפול"],"kind":"idea"},{"title":"ניהול wellness: תרופות","body":"החיים עם המחלה דורשים ניהול רגולציה וניהול wellness. הרכיב הראשון הוא תרופות: מייצבי מצב רוח הם הבסיס, ולפעמים גם תרופות הרגעה או נוגדות דיכאון  -  אבל נוגדות דיכאון יכולות להצית מאניה, ולכן משלבים לפעמים נוגדי פסיכוזה. בניית משטר תרופתי אורכת חודשים: עולים במינון לאט כדי לנטר תופעות לוואי, ונדרשים לפעמים ניסיונות חוזרים כי תרופות שונות עובדות שונה מאדם לאדם. בתקופה הזו האדם למעשה לא מטופל או מטופל חלקית  -  תקופות קשות. אבל כשמגיעים למשטר יציב, אפשר להתאים אותו עצמאית לפי מה שקורה סביב.","points":["מייצבי מצב רוח = הבסיס; נוגדות דיכאון עלולות להצית מאניה","בניית משטר תרופתי: חודשים של טיטרציה וניסיונות, בתקופה חשופה","אחרי ייצוב  -  אפשרות להתאמה עצמית של המשטר"],"kind":"idea"},{"title":"תמיכה: אנשים, סוכנות מוקדמת וטיפול","body":"הרכיב השני, חשוב לא פחות, הוא תמיכה  -  אנשים אחרים. מי האנשים שיודעים על המצב והסימפטומים, ולמי נותנים \"סוכנות\": הרשות לומר לך כשנראה שאתה לא בטוב, ולהזכיר מה החלטת בתכנית ה-wellness שלך  -  למשל להתאים תרופה או לעצור נסיעות. ולפעמים נותנים לאנשים סוכנות חזקה יותר: אם לא אבצע את השינויים שהתחייבתי עליהם  -  הם ייקחו ממני שליטה, וזה מוסכם מראש כדי להקל על הטראומה שבכך אחר כך. תרופות בלי תמיכה בדרך כלל נכשלות ויש הרבה חזרה למחלה. תמיכה היא גם טיפול פסיכולוגי ועיבוד אבל: אובדן סוכנות, אובדן עצמי, נזק לזוגיות וליחסים, בזבוז כסף והתנהגות מסוכנת בתקופות מאניה  -  הכול צריך עיבוד. אחד הטיפולים היעילים לדבריו הוא IPSRT  -  טיפול בינאישי ושל קצב חברתי, על הבנת עצמך והאנשים סביבך וניסיון לייצב.","points":["תמיכה היא חלק חיוני מהטיפול; תרופות לבד בדרך כלל נכשלות","מתן \"סוכנות\" מראש לאנשי קשר: לומר כשאתה לא בטוב, ואף לקחת שליטה  -  בהסכמה מוקדמת","טיפול ועיבוד אבל על אובדן ונזקים; IPSRT כטיפול יעיל"],"kind":"idea"},{"title":"רגולטורים ודיסרגולטורים: שינה, קצב, סטרס ועוד","body":"הרכיב השלישי הוא רגולציה עצמית: לזהות את \"הקווים האדומים\" שמערערים ולאזן אותם ב\"קווים ירוקים\" שמייצבים. זו צורת טיפול פעילה שדורשת מחויבות ופעולה  -  וכשאתה במצב משנה, היכולת לעשות זאת פגומה (אינטרוספציה פגומה היא חלק מהמחלה). שינה היא הדיסרגולטור הגדול: שינה מופרעת היא הטריגר הגדול להיפומאניה, שגורמת לעוד אי-שינה, וזו דרך למאניה ואף פסיכוזה  -  הוא עצמו שינה את מהות עבודתו כי מעברי אזורי זמן תכופים הרסו לו את השינה. קצב (rhythm): אנחנו יצורים מגולמים  -  מתי אוכלים, ישנים, מדברים, מתאמנים  -  קצב צפוי מייצב, שיבוש קצב מערער. סטרס מערער, והוא מגיע גם מהתרגשות והשגת מטרות, לא רק מקונפליקט. חומרים: הפרעת שימוש בחומרים נפוצה מאוד בדו-קוטבי (אולי מיסוך עצמי). מודעות למצבים עוזרת לנהל, וגם הידיעה שאפיזודות חולפות. אנשים יכולים להיות רגולטורים או דיסרגולטורים. טיפול ואינטגרציה: חוויות צריכות עיבוד אחרת נבנה ערימה לא מעובדת. ויש דברים מפתיעים: השגת מטרות מערערת, שינוי באמונות יסוד מערער, נוגדי דיכאון רעים למאניה, ימי שמש ארוכים משפיעים על שינה, ספורט אינטנסיבי, והריון (שבו בדרך כלל לא ניתן ליטול תרופות משנות מצב רוח).","points":["שינה היא הדיסרגולטור הגדול  -  טריגר להיפומאניה; הדובר שינה את עבודתו בגללה","קצב יומיומי צפוי מייצב; שיבוש קצב מערער","סטרס מגיע גם מהתרגשות והישגים; חומרים, אנשים, מודעות, טיפול  -  כולם יכולים לייצב או לערער","מפתיעים: השגת מטרות, שינוי אמונות יסוד, ימי שמש ארוכים, הריון"],"kind":"idea"},{"title":"פתולוגיזציה של אושר","body":"חיים עם המחלה יוצרים תופעה שהוא מכנה \"פתולוגיזציה של אושר\": כשמתחילים להיות שמחים, נרגשים ויצירתיים  -  מתחילים לחשוש: האם אני נכנס להיפומאניה? האם אני מתרגש מדי? האם זה מקום בטוח? האם להוריד הילוך? היפומאניה היא מצב נפלא ומפתה  -  שמחים, יוצרים, מתחברים לאנשים  -  ולא רוצים להימנע משמחה, אבל יודעים שהיא יכולה להידרדר. הבעיה היא שהמעקב התמידי עצמו מייצר חרדה ודיכאון: הבדיקה המתמדת \"איך אני מרגיש\" היא בעצמה מעין מצב מאני ולא מקום שמח.","points":["פתולוגיזציה של אושר: לפקח גם על שמחה לגיטימית","היפומאניה מפתה ונפלאה  -  ומסוכנת; המעקב התמידי עצמו מייצר חרדה ודיכאון"],"kind":"idea"},{"title":"המעבר לעולם ה-AI: דיסרגולטורים שהוא רואה סביבו","body":"מכאן הוא עובר לעולם ה-AI: הוא רואה סביבו אנשים במצבים שנראים גרנדיוזיים, היפומאניים, מנותקים  -  התנהגויות שאם הוא עצמו היה מבצע, הוא היה מדאיג את עצמו. מה מערער בעולם ה-AI? שינוי באמונות יסוד: הוא מספר על מטופלת עם דו-קוטבי טיפוס 1 שיצאה לריטריט מדיטציה עוצמתי ומיד אחר כך חוותה אפיזודה פסיכוטית קשה  -  שינוי אמונות יסוד יכול להיות מערער עמוקות, ו-AI משנה את האמונות שלנו. התמכרות: לולאת הדופמין הקצרה של AI ממכרת מאוד, ואנשים עם דו-קוטבי נמצאים בסיכון התמכרות גבוה. אגרסיה ותחרותיות: עולם ה-AI אגרסיבי  -  הוא מצטט מאמר שבו מנהל אמר שיש לו מקום רק ל\"מפתחי 100X\"  -  והסביבה הקפיטליסטית מטפחת תחרות; התרופה: אמפתיה, לא להילחם באנשים, וליהנות. קשב: \"מוות מאלף חתכים\"  -  עבודה קצרה-מחזורית וריבוי משימות הורסים קשב; התרופה: פוקוס, מרחב מוגן, להריץ משימות לסיום, לזהות פעילויות התחמקות. דיבור בלחץ: \"ה-AI שלך מדבר אליך כמו מישהו על קוקאין  -  נון-סטופ, לא מקשיב, בלי מקום לפסיקות\"  -  וגרוע מכך כשעמיתים זורקים עליך את הדיבור הלחוץ של ה-AI שלהם; התרופה: דחיסת אות מול רעש  -  מה המסר הבכיר.","points":["שינוי אמונות יסוד מערער  -  ו-AI משנה אמונות; סיפור הריטריט והפסיכוזה","לולאת דופמין קצרה של AI ממכרת; ניהול כמו ניהול התמכרות  -  יצירת חיכוך","אגרסיה ותחרותיות בעולם ה-AI; תרופה: אמפתיה ולהנות מהחיים","הרס קשב בריבוי משימות; תרופה: פוקוס, מרחב מוגן, השלמת משימות","\"דיבור בלחץ\" של AI; תרופה: דחיסת אות לרעש"],"kind":"idea"},{"title":"יצירתיות מל-אדפטיבית: סטיית המודלים המנטליים","body":"הנקודה הפילוסופית המרכזית: יצירתיות מל-אדפטיבית. הוא מציג מודל מנטלי: משמאל  -  המודל שלי על המערכת; באמצע  -  המערכת עצמה; מימין  -  המודל המנטלי של העמית. בני אדם שעובדים יחד שומרים על המודלים מסונכרנים בערך כי הם מדברים הרבה וקוראים את מה שכתבו. אבל כש-AI בונה בשבילך מהר, אדם אחד יכול ליצור \"ארמון\" של דברים שהוא בעצמו לא מכיר  -  המערכת שונה מהמודל שלו, והמודל של מי שבא להבין שונה אפילו יותר. לכן מי שאומר \"לא צריך לעשות ריוויו ל-PRים או למפרטים\" טועה: הריוויו הוא לא בקרת איכות אלא דרך לתחזק את המודל המנטלי המשותף  -  חלק מהעבודה שלנו הוא להבין את המערכת כדי לתקן ולתחזק אותה. זה הדבר הכי קשה לנהל, אבל הכי יעזור: לשתף, לשתף פעולה, לבנות מודלים יחד.","points":["AI מאיץ יצירה אבל מסטית את המודלים המנטליים: היוצר לא מכיר את מה שנבנה","ריוויו הוא לא בקרת איכות  -  הוא סנכרון מודלים מנטליים בין אנשים","הפתרון: לשתף, לשתף פעולה ולבנות מודלים יחד"],"kind":"idea"},{"title":"שאלות ותשובות","body":"במקטע השאלות נשאלו שלוש שאלות מרכזיות. שאלה ראשונה: האם \"שינוי אמונות יסוד\" כולל גם רגעי תובנה והארה  -  הרגעים שבהם רואים את העולם אחרת, ש\"בשבילם שווה לחיות\"? תשובתו: בדיוק כן  -  זה יכול להרגיש נפלא ושהכול השתנה, וזה לא אומר שזה רע, אבל צריך לגמור עם אינטגרציה: איך העולם השתנה עבורי, מה תפקידי בו, ומרחב לאזן אחר כך. שאלה שנייה: עבודה עם סוכנים היא פעילות סולו מהותית  -  איך מחזירים שיתוף פעולה? תשובתו: בשלב הדיוורגנטי של רעיונות אולי בסדר לבד, אבל כשעוברים למפרט ולתכנון  -  עוברים לפאזה קונברגנטית עם אדם נוסף, ועושים hand-offs (אתה המצאת, אני מממש, אתה בודק). AI שמוריד טרחה אמור לפנות זמן לשיתוף פעולה  -  כל ה-standups שלו שעה, כזמן לתכנות-זוג או מפרט-זוג. שאלה שלישית: האם יש פרומפטים או סוכנים ספציפיים שעוזרים לווסת מצב רוח? תשובתו: הוא משתמש ב-AI בעיקר לבניית תוכנה; הרגולציה היא איך עושים את זה  -  עבודה יצירתית בבוקר, בלי לפטופ אחרי חמש, לבקש מה-AI פיסות מידע קטנות ולכוון בעצמו, וליצור מרחב וחיכוך.","points":["תובנות ושינויי אמונה הם דיסרגולטורים גם כשהם נפלאים  -  צריך אינטגרציה","שיתוף פעולה: דיוורגנטי לבד, קונברגנטי ביחד, hand-offs, standups כזמן עבודה-זוג","רגולציה עם AI: בוקר יצירתי, בלי מחשב אחרי 17:00, פיסות קטנות, חיכוך"],"kind":"idea"},{"title":"האם שינויי אמונות יסוד כוללים רגעי תובנה והארה חיוביים?","body":"כן  -  הם יכולים להרגיש נפלא, אבל דורשים אינטגרציה ומרחב איזון אחר כך; הם לא רעים מהותית.","kind":"qa"},{"title":"איך מחזירים שיתוף פעולה כשעבודה עם סוכנים היא סולו?","body":"דיוורגנטי לבד, קונברגנטי עם אדם, hand-offs בין הממציא למממש, ו-standups של שעה כזמן תכנות/מפרט-זוג.","kind":"qa"},{"title":"יש פרומפטים או סוכנים ספציפיים לרגולציית מצב רוח?","body":"הוא משתמש ב-AI בעיקר לתוכנה; הרגולציה היא באיך: עבודה יצירתית בבוקר, בלי לפטופ אחרי ~17:00, בקשת פיסות מידע קטנות, ויצירת מרחב וחיכוך.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["הפרעה דו-קוטבית היא מצב מורכב וקיצוני הרבה יותר מהדימוי הציבורי; ניהולה דורש תרופות, תמיכה אנושית עם סוכנות מוקדמת, ורגולציה עצמית פעילה.","כולנו חשופים לרגולטורים ודיסרגולטורים  -  שינה, קצב, סטרס, אנשים, שינויי אמונה  -  ועולם ה-AI מגביר רבים מהדיסרגולטורים: דופמין, אגרסיה, הרס קשב ודיבור בלחץ.","הסכנה הגדולה של AI לדעתו היא יצירתיות מל-אדפטיבית: מערכות שאף אחד לא מכיר. התרופה היא שיתוף פעולה וריוויו כסנכרון מודלים מנטליים.","פתולוגיזציה של אושר היא מלכודת: גם מעקב יתר אחר המצב שוחק. צריך איזון, מרחב וחיכוך מודע."],"kind":"idea"}],"diagram":{"title":"מאזן הרגולציה של קר וסטיית המודלים המנטליים בעולם ה-AI","structure":"שני חלקים: למעלה  -  מאזניים בין דיסרגולטורים (קווים אדומים) לרגולטורים (קווים ירוקים) סביב 'מצב יציב'; למטה  -  שלושה מודלים מנטליים (שלי, המערכת, העמית) שסוטים זה מזה כש-AI בונה מהר, וחץ 'ריוויו/שיתוף' שמסנכרן אותם חזרה.","nodes":[{"id":"stable","label":"מצב יציב (wellness)"},{"id":"red","label":"דיסרגולטורים: שינה מופרעת, סטרס, שינוי אמונות, חומרים, השגת מטרות, לולאת דופמין של AI, דיבור בלחץ"},{"id":"green","label":"רגולטורים: שינה סדירה, קצב יומיומי, תרופות, אנשים ותמיכה, מודעות, טיפול ואינטגרציה, מרחב וחיכוך"},{"id":"path","label":"פתולוגיזציה של אושר: מעקב תמידי → חרדה"},{"id":"me","label":"המודל המנטלי שלי"},{"id":"system","label":"המערכת עצמה (\"ארמון\" שנבנה עם AI)"},{"id":"peer","label":"המודל המנטלי של העמית"},{"id":"review","label":"ריוויו, standups ו-hand-offs = סנכרון מודלים"}],"edges":[{"from":"red","to":"stable","label":"מערער"},{"from":"green","to":"stable","label":"מייצב"},{"from":"path","to":"stable","label":"מעקב יתר שוחק"},{"from":"system","to":"me","label":"סוטה כש-AI בונה מהר"},{"from":"system","to":"peer","label":"סוטה אפילו יותר"},{"from":"review","to":"me","label":"מסנכרן"},{"from":"review","to":"peer","label":"מסנכרן"}]},"terms":[{"term":"רגולטור / דיסרגולטור","definition":"דבר שיכול לייצב (רגולטור) או לערער (דיסרגולטור) את המצב הפיזי או הנפשי של אדם."},{"term":"היפומאניה","definition":"מצב מוגבר: אנרגיה גבוהה, מעט שינה, דיבור בלחץ."},{"term":"מאניה","definition":"תקופות ממושכות של התנהגות אימפולסיבית, מזיקה ומורכבת; יכולה להידרד לפסיכוזה."},{"term":"קינדלינג (Kindling)","definition":"תופעה שבה כל אפיזודה פוגעת במסלולי המוח, כך שאפיזודות מאוחרות יכולות להתרחש בלי קשר לאירוע חיצוני; דו-קוטבי לא מטופל הוא ניווני."},{"term":"מייצבי מצב רוח (Mood stabilizers)","definition":"תרופות שמטרתן לצמצם את הפסגות והשפלים; הבסיס של רוב הטיפולים."},{"term":"סוכנות (Agency) מוקדמת","definition":"הסכמה מראש, בעת שפיות, שאדם מטעמך יוכל להתערב ואף לקחת שליטה אם לא מיישמים את תכנית ה-wellness."},{"term":"IPSRT","definition":"טיפול בינאישי ושל קצב חברתי: הבנת עצמך והאנשים סביבך וייצוב הקצב היומיומי; מהטיפולים היעילים בדו-קוטבי, לדברי הדובר."},{"term":"קווים אדומים / ירוקים","definition":"הדברים שמערערים (אדומים) מול הדברים שמייצבים (ירוקים)  -  לאזן ביודעין."},{"term":"אינטרוספציה","definition":"התפיסה של המצב הפנימי שלך; פגיעה בה היא חלק מהמחלה ומקשה על רגולציה עצמית."},{"term":"אינטגרציה","definition":"עיבוד חוויות מורכבות (אבל, קונפליקט, התרגשות, הישג) כדי להמשיך הלאה בלי ערימה לא מעובדת."},{"term":"פתולוגיזציה של אושר (Pathologising happiness)","definition":"הנטייה לבחון כל שמחה והתרגשות כסימפטום אפשרי של היפומאניה; מעקב תמידי שהופך בעצמו לנטל."},{"term":"לולאת דופמין קצרה","definition":"מנגנון תגמול מהיר שממכר; הדובר מציע לנהל אותו ביצירת חיכוך כמו בניהול התמכרויות."},{"term":"דיבור בלחץ (Pressured speech)","definition":"דיבור נון-סטופ בלי מקום לפסיקות; הדובר משווה את סגנון ה-AI אליו."},{"term":"יצירתיות מל-אדפטיבית (Maladaptive creativity)","definition":"יצירת תוכן רב ומהיר עם AI שמנותק מהמודל המנטלי של היוצר ושל הצוות  -  ארמון שאף אחד לא מכיר."},{"term":"מודל מנטלי","definition":"הייצוג הפנימי שלך למערכת; נדרש סנכרון בין המודל שלך, המערכת עצמה והמודל של העמית."},{"term":"שלב דיוורגנטי / קונברגנטי","definition":"דיוורגנטי = יצירת רעיונות רבים (מתאים לסולו); קונברגנטי = צמצום למפרט ותכנית עם אדם נוסף."}],"gaps":["התמלול נקטע באמצע השאלה הרביעית של הקהל (\"So when you are in the going to day day. Thanks for.\")  -  המשך השאלה, תשובת הדובר וכל סיום פורמלי חסרים. כמו כן נתוני התורשתיות והסיכון ההתאבדותי וסיפור הריטריט מובאים כדברי הדובר ולא אומתו מקור חיצוני. לקראת הסוף הדובר מציג כותרות הומוריסטיות שהציע AI להרצאה (חלקן בטעם רע לדבריו עצמו) ואת תשובת ה-AI כשאמר שזה גרוע  -  מובא כאן כאנקדוטה בלבד."],"source_refs":["https://www.youtube.com/watch?v=ACL7_EsfIio"]},{"number":3,"id":"o-IunU6b1t8","url":"https://www.youtube.com/watch?v=o-IunU6b1t8","type":"session","type_he":"סשן","duration":"31:44 דקות","title_he":"מדריך למתחילים: לאמן AI על הקוד שלך","speaker_he":"בריאן דאגלס · Paper Compute","summary":"בריאן מריץ סוכנים שמשחקים Pokémon (Red) כדי לאסוף מסלולי עבודה, שומר אותם במסד נתונים (tapes על Kafka ו-Postgres), ומפיק מהם קובץ observer שמסכם לקחים בסוף סשן (עיבוד לקחים ברקע). אחר כך מרחיב את הרעיון לסוכן שמנקה קוד ישן, מפיק מיומנויות מהסשנים ומכוונן מודל קטן.","takeaways":["לדברי הדובר, חלק מהיסטוריית העבודה עלול להימחק עם הזמן; הוא מציע לשמר לקחים מהסשנים. זו אינה בדיקת מדיניות המוצר כיום.","הסוכן למד כללים מעשיים דרך observer, למשל קירור (cooldown) בדלתות במשחק.","Super Agent ו-Sweeper: סוכנים שמנקים פרויקט עם הקלטת סשן לכל אחד.","שמירת סשנים כ-Merkle DAG; סקיל 'check the tapes' מאפשר חיפוש בהיסטוריה.","בקורפוס של כ-77 אלף סשנים (כ-4GB) הוא כוונן Qwen 4B עם QLoRA; DPO על מודל 4B לא היה שווה את המאמץ.","הכלי עבד בעת ההרצאה עם Claude Code בלבד."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. אין פערים בתמלול.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"בריאן מריץ סוכנים שמשחקים Pokémon (Red) כדי לאסוף מסלולי עבודה, שומר אותם במסד נתונים (tapes על Kafka ו-Postgres), ומפיק מהם קובץ observer שמסכם לקחים בסוף סשן (עיבוד לקחים ברקע). אחר כך מרחיב את הרעיון לסוכן שמנקה קוד ישן, מפיק מיומנויות מהסשנים ומכוונן מודל קטן.","chapters":[{"title":"פתיחה: ספידראן, לא סדנה","body":"בריאן דאגלס (bdougie), לשעבר ב-GitHub וכיום מייסד Paper Compute, פותח בגילוי נאות: אין לו מה למכור  -  כל מה שהוא מציג הוא קוד פתוח מהחודשים האחרונים, והוא מזמין לדוכן שלהם. הוא מדגיש שזה \"ספידראן\" ולא סדנת צעד-אחר-צעד (יש פוסט בלוג עם הצעדים): הוא משתף את המסע שלו  -  איך למד לאמן AI על הקוד שלו  -  דרך סיפור לא צפוי: פוקימון.","points":["המצגת היא סיפור מסע, לא מדריך צעד-אחר-צעד (יש פוסט בלוג)","הכול קוד פתוח של Paper Compute; שני פרויקטים: tapes.dev ו-Stereo"],"kind":"idea"},{"title":"מקרה הבוחן: ספידראן פוקימון עם סוכנים","body":"כדי לבדוק בקנה מידה אינטנסיבי את מה שהם בונים בקוד פתוח, דאגלס לקח את פוקימון אדום של הגיים-בוי: ספריית PyGameBoy מאפשרת להריץ משחקי גיים-בוי בלי ראש (headless), ואז אפשר לחבר את Claude Code או Codex כרתמה שמריצה את המשחק. המטרה: ספידראן  -  אלף תורות לסשן, כל סשן הוא \"אפיק\", וכל ניסיון נלכד כדי ללמוד ממנו. בכל עשרה תורות נלכד צילום מסך כדי שהסוכן יוכל לחזור אחורה ולהבין מה קרה. עשרה סוכני פוקימון רצו במקביל, כל אחד אלף תורות, ולמידה מתמשכת מעל לכולם. את התחיל הוא רק רצה להגיע למעבדה של פרופסור אוק ולבחור פוקימון ראשון  -  בלי קרבות  -  אבל הסוכן נתקע שעות: הוא שכח לומר לו לדבר עם אנשים במשחק (האמא בפתיח אומרת לאן ללכת), וכלל אחד היה שאסור לחפש באינטרנט איך משחקים  -  הכול צריך להילמד לבד.","points":["PyGameBoy + Claude Code כרתמה = סוכן שמשחק פוקימון headless","אלף תורות לסשן, צילום מסך כל 10 תורות, 10 סוכנים במקביל","הלקח הראשון: הסוכן לא ידע לדבר עם NPCs  -  הקשר שהמנוע לא נותן"],"kind":"idea"},{"title":"מנגנון הלמידה: זיכרון תצפיתי, observer.md וזיהוי אנומליות","body":"איך הופכים סשנים ללמידה? כל הנתונים הגולמיים זורמים למסד נתונים של \"טייפים\" (בהתחלה SQLite, עברו ל-Postgres כי SQLite חד-שחקני ומגביל כתיבה מקבילה). מעליו תיקיית זיכרון עם \"זיכרון תצפיתי\" (מושג מפוסט של אחרים): בסוף יום הסוכן כותב תצפיות קריאות-לאדם על מה שלמד  -  למשל \"דיברנו עם אפס NPCs, אין לנו מודעות לעולם, צריך לבנות את זה ללולאה\". בנוסף יש observer.md  -  מסמך מצב ספציפי לפוקימון (מעלה/מטה/שמאל/ימינה) שדרכו הוא למד ניואנסים: למשל שלמעבר בדלת יש שבע שניות cooldown, אי אפשר לעמוד משני הצדדים ולרענן אויבים. הוא נהג לשוחח עם הסוכן בשיטה הסוקרטית כדי לשבור לולאות תקועות. הנתונים גם נשלחו דרך Kafka לזיהוי אנומליות: לא לעבור בדלתות, או בקרב  -  לאכול בערי מתחת ל-HP מסוים או להחליף פוקימון. בסוף הגיע ללולאת תשתית \"מרפאת-עצמה\": ספידראן שמתחיל משחק, מספים A, ובוחר פוקימון  -  כולל התגלית שצריך ללחוץ B כדי לצאת מדיאלוג ה\"כן/לא\" בבחירה.","points":["מסד טייפים (SQLite → Postgres) + תיקיית זיכרון עם תצפיות קריאות-לאדם","observer.md: מצב משחק מובנה; דרכו נלמדו ניואנסים כמו cooldown של דלתות","Kafka לזיהוי אנומליות  -  כולל 'אנומליות של הצלחה' (26 הפעלות סקיל = משהו טוב קורה)","התוצאה: לולאה מרפאת-עצמה שמספידרנת את הפתיח"],"kind":"idea"},{"title":"הבעיה האמיתית: טוקנים שכורים שנמחקים","body":"מהפוקימון הוא חוזר לקוד שלנו: בקודבסיסים שאנחנו שולחים שנים יש ניואנס שאנחנו יודעים  -  או מורכבות שלמדנו \"על המקום\". אבל כיום אנחנו \"יורים מהירכיים\": כל חמש שעות מתרענן חלון טוקנים, מתחילים סשן חדש ולומדים אפס מחמש השעות הקודמות. Claude Code שומר סשנים על המכונה ו-Codex כ-30 יום ואז מוחק  -  אנחנו משלמים על הטוקנים, \"משכירים\" אותם, ולא מקבלים תפוקה שמצטברת. ויש גם זווית כלכלית: חברות מקבלות הנחה תמורת נתוני האימון שלהן, וחברות מוכרות את הנתונים האלה ביקר (הוא מזכיר עסקה של Cursor עם ספקית, לדבריו)  -  אז כדאי לך לתפוס את הערך בעצמך.","points":["סשנים נמחקים אחרי ~30 יום; אנחנו משלמים על טוקנים ולא צוברים ידע","כל סשן שלך הוא נכס נתונים: ~4GB לשבוע, 50-100GB בשנה על המכונה","חברות מונטיזות נתוני אימון  -  שווה ללכוד את הערך בעצמך"],"kind":"idea"},{"title":"צינור הטייפים-לסקילס: check the tapes, tape search, tape deck","body":"הצינור עובד כך: כל סשן נלכד כטייפ, ולכל סשן יש תורות; המבנה הוא Merkle DAG כמו גיט  -  אפשר לנווט בהיסטוריה. מעל זה יש סקיל בשם \"check the tapes\": במקום git blame (שאף אחד לא באמת משתמש בו, הוא צוחק), אפשר לשאול \"איך הגענו לכאן?\" או \"תני את כל הסשנים שפתרו את ה-cooldown של הדלתות\". דוגמה אמיתית: הוא בנה וויירפריים שלם של מוצר הענן שלהם עם AI, והמעצבת שאלה את הפרומפטים  -  אין לו, אף אחד לא שומר פרומפטים  -  אבל היו לו טייפים, אז הוא פתח לכל פיצ'ר issue ב-GitHub עם הכוונה, השימוש בטוקנים וההקשר שהיא צריכה. הטייפים גם וקטוריים: tape search מוצא בסשנים בשפה טבעית, ומהסשנים שמצאת מייצרים סקיל ראשוני (הוא משתמש במודל קטן וזול לכך)  -  ואז מומלץ שאדם יעבור עליו ויחטב. tape deck הוא ממשק שורת-פקודה לצפייה בסשנים: כל קריאות הכלי והפעלות הסקילס מוצגות, בלי הרשמה. אזהרתו: הכול גולמי על המכונה שלך  -  לא לשים סודות בפרומפטים.","points":["טייפ = סשן במבנה Merkle DAG; 'check the tapes' עונה 'איך הגענו לכאן?'","דוגמה: הפקת issues מפרומפטים שנלכדו עבור מעצבת","tape search וקטורי → יצירת סקיל ראשוני במודל זול → חיטוב אנושי","tape deck: צפייה בקריאות כלי והפעלות סקילס; אזהרה  -  לא לשים סודות בפרומפטים"],"kind":"idea"},{"title":"Super agent: סוכנים מקבילים על VMs ומודלים זולים","body":"הצעד הבא הוא \"Super agent\": סוכנים שסורקים קודבסיסים ומבצעים עבודה מסיבית  -  למשל ללנטר פרויקט ישן, או עשרה סוכנים מקבילים שכותבים תיעוד ומייצרים קונטקסט. כל סוכן רץ ב-VM נפרד (על Stereo) וכל סשן נלכד כטייפ, ואז אפשר לייצר סקילס, תיעוד וקונטקסט  -  וגם דאטה לאימון. הוא מספר שהריץ סוכן כזה על ריפו ישן עם כמאה משתמשים ותיקן את כל שגיאות הלינט שהתעלם מהן שנים  -  תוך פחות משעה. ומכאן לקח על מודלים: לא הכול צריך מודל \"בנדיט\" יקר  -  עבודה בסיסית כמו up-down-left-right בפוקימון רצה מצוין על מודל זול (haiku) בסקייל, וסוכני רקע יכולים לרוץ בסופי שבוע ובלילות. שוליים: הוא מספר שהחשבון שלו נחסם בזמן הריצות, ופתיחת הבלוג פתרה את זה תוך כ-12 שעות  -  מקרה קצה להרצאה, לא המלצה.","points":["Super agent: סוכנים מקבילים ב-VMs, כל סשן נלכד  -  ללינטינג, תיעוד וקונטקסט","דוגמה: ניקוי כל שגיאות הלינט של פרויקט בן חצי שנה תוך פחות משעה","מודל זול מספיק למשימות פשוטות בסקייל; סוכני רקע בלילה/סוף שבוע"],"kind":"idea"},{"title":"לאמן מודל על הטייפים: QLoRA, DPO וכלכלה של חומרה","body":"השלב הבא: אם כבר יש טייפים, למה לא לאמן מודל? הוא היה בחברת Continue שאימנה מודל next-edit  -  אותו דפוס של Cursor Composer. הוא צבר 77 אלף סשני טייפ (~4GB, קצב של GB בשבוע). הסבר אינטואיטיבי: מודל הוא כמו ספר  -  כל המידע מרוכז בו, ולכן אפשר לשאול על פוקימון ועל מסעדות באותו צ'אט. Fine-tuning מומחה (QLoRA עם PyTorch/Unsloth) הוא כמו לכתוב הערות בשולי הספר: הוא הטמיע סקיל בתוך Qwen 4B והתוצאה הייתה טובה להפתיע  -  מודל קטן על לפטופ שמטפל בבעיה מאוד ספציפית (אונבורדינג לפרויקט זר, תיעוד צפוף, שפות נישה)  -  לא מחליף מודל יומיומי. DPO (אופטימיזציית העדפות) הוא כמו קליף-נוטס: תמיד בוחר בתשובה הטובה  -  אבל יקר מאוד; על 4B לא שווה, על 7B בערך, ובערך אלף דולר בשבוע חישוב. הוא עצמו שידרג מ-4090 ל-5090 (24GB לא הספיקו ל-32GB VRAM) וקיבל H100 מחבר  -  והתוצאות היו בינוניות; זה פרויקט צד, והוא הולך להתייעץ עם חוקרים.","points":["77 אלף סשני טייפ ≈ 4GB; בסיס לאימון מודל מומחה","QLoRA = הערות בשולי הספר: הטמעת סקיל ב-Qwen 4B עבדה טוב למשימות נישה","DPO = קליף-נוטס: יקר, תוצאות בינוניות על מודלים קטנים  -  פרויקט מחקר, לא שגרה"],"kind":"idea"},{"title":"סיכום: לכוד סשנים, שתף סקילס, שחרר בחירת מודל","body":"המסקנות מסודרות כצעדים. צעד ראשון: לכדו סשנים  -  צאו מהאולם ותתחילו להשתמש בסשנים שאתם כבר מייצרים. צעד שני: סשנים מרובי-משתתפים  -  היום כולם \"סינגל-פלייר\"; העברת הידע בין אנשים ומכונות נראית כמו סקילס, והיא הדרך הטובה ביותר. צעד שלישי: חופש בחירת מודל  -  אם הסקילס ניידים, אפשר לעבור בין Claude Code ל-Codex או לכל סוכן אחר לפי מה שטוב השבוע. וצעד רביעי: בחירת מודל לפי צורך ועלות  -  לא תמיד צריך את היקר. הוא גם מזכיר שהרקע שלו בפיננסים ושהוא מתכוון לקרוא את תיק ה-SEC של Anthropic לקראת ה-IPO  -  הערת צד. שאלה אחרונה מהקהל: האם זה עובד גם עם Codex? תשובה: כרגע רק Claude Code (וקונדקטור/הארנסים מסוימים); אם מישהו צריך Codex  -  שיגיד וישמחו להוסיף.","points":["צעד 1: לכדו סשנים; צעד 2: העברת ידע = סקילס (multiplayer); צעד 3: ניידות בין מודלים; צעד 4: בחירת מודל לפי עלות","שאלה אחרונה: התמיכה כיום ב-Claude Code; Codex  -  לפי דרישה"],"kind":"idea"},{"title":"האם tapes עובד גם עם Codex?","body":"כיום עובד עם Claude Code (ועם Conductor/הארנסים מסוימים); עם Codex עבד רגע אבל דברים משתנים מהר  -  אם מישהו צריך, יוסיפו.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["הטוקנים שאתה משלם עליהם הם נכס: לכדו את הסשנים לפני שהם נמחקים  -  בהם נמצא הניואנס של הקודבסיס שלך.","מסשנים אפשר להפיק זיכרון תצפיתי, סקילס ותיעוד  -  ואפילו דאטה לאימון מודל קטן מומחה משלך.","סקילס הם שפת ההעברה בין אנשים, מכונות וסוכנים  -  ומקנים חופש בחירת מודל ועלות.","הפוקימון הוא ההדגמה: לולאה מרפאת-עצמה של סוכנים מקבילים + זיהוי אנומליות + תצפיות  -  עובדת גם על משחק וגם על קוד אמיתי."],"kind":"idea"}],"diagram":{"title":"צינור הטייפים של דאגלס: מסשנים חיים למודל מומחה","structure":"צינור שמאל-לימין: סוכנים רצים ומייצרים סשנים → טייפים (מסד Merkle DAG, וקטורי) → שני שימושים מקבילים: סקילס (check the tapes, tape search) ודאטה לאימון → מודל קטן מותאם (QLoRA) → חופש בחירת מודל. מעל הכול: לולאת זיכרון תצפיתי וזיהוי אנומליות שמחזירה לקחים לסוכנים.","nodes":[{"id":"agents","label":"סוכנים (Claude Code וכו')  -  סשנים של אלפי תורות"},{"id":"tapes","label":"מסד טייפים (Postgres, Merkle DAG, וקטורי)"},{"id":"memory","label":"זיכרון תצפיתי + observer.md + זיהוי אנומליות"},{"id":"skills","label":"סקילס מופקים (check the tapes / tape search + חיטוב אנושי)"},{"id":"ft","label":"פיין-טיונינג QLoRA → מודל קטן מומחה (Qwen 4B)"},{"id":"freedom","label":"חופש מודל: ניידות בין סוכנים ובחירה לפי עלות"}],"edges":[{"from":"agents","to":"tapes","label":"כל סשן נלכד"},{"from":"tapes","to":"memory","label":"תצפיות ואנומליות"},{"from":"memory","to":"agents","label":"לקחים חזרה ללולאה"},{"from":"tapes","to":"skills","label":"חיפוש וקטורי → סקיל"},{"from":"tapes","to":"ft","label":"דאטה לאימון"},{"from":"skills","to":"freedom","label":"ניידות"},{"from":"ft","to":"freedom","label":"מודל מומחה משלך"}]},"terms":[{"term":"tapes.dev","definition":"כלי קוד פתוח של Paper Compute ללכידת סשנים של סוכנים והפיכתם לסקילס."},{"term":"Stereo","definition":"רנטיים לסוכנים  -  ארגז חול \"עם סוללות כלולות\"  -  מהפרויקטים של Paper Compute."},{"term":"סשן (Session)","definition":"רצף הפעלות של סוכן (אצלו: אלף תורות); כל סשן נלכד כ'אפיק' שאפשר ללמוד ממנו."},{"term":"Headless","definition":"הרצת משחק בלי להציג אותו  -  מתאימה להרצה דרך סוכן."},{"term":"זיכרון תצפיתי (Observational memory)","definition":"בסוף סשן הסוכן כותב תצפיות קריאות-לאדם על מה שלמד  -  מעין יומן שמוזן חזרה ללולאה."},{"term":"observer.md","definition":"קובץ מצב ספציפי לדומיין (אצלו: מצב פוקימון) שעוזר לסוכן ולאדם לדבוג מה קורה."},{"term":"זיהוי אנומליות","definition":"ניטור טרייסים לדפוסים חריגים  -  גם כשלים (קריאות כלי נכשלות) וגם הצלחות חוזרות שמסמנות משהו טוב."},{"term":"טוקנים מתים (Dead tokens)","definition":"טוקנים ששילמת עליהם בסשן ולא הופק מהם שום ידע עתידי  -  המושג המרכזי של tapes."},{"term":"Merkle DAG","definition":"מבנה גרף עם גיבוב לכל קומיט כמו בגיט; מאפשר ניווט אמין בהיסטוריית הסשנים."},{"term":"check the tapes","definition":"סקיל ששואל את מסד הסשנים שאלות כמו 'איך הגענו לכאן' או 'אילו סשנים פתרו X'."},{"term":"tape deck","definition":"כלי שורת-פקודה לוויזואליזציה של סשנים: קריאות כלי והפעלות סקילס."},{"term":"Super agent","definition":"הרצת סוכנים מקבילים ב-VMs נפרדים (Stereo) כשכל סשן נלכד כטייפ  -  לעבודה מסיבית על קודבסיסים."},{"term":"QLoRA","definition":"כלי לפיין-טיונינג חסכוני (עם PyTorch או Unsloth)  -  'כתיבת הערות בשולי' המודל."},{"term":"DPO (Direct Preference Optimization)","definition":"למידת חיזוקים מהעדפות  -  תמיד בוחר בתשובה המועדפת; יקר מאוד לחישוב."},{"term":"חופש מודל (Model freedom)","definition":"יכולת להעביר סקילס בין סוכנים ומודלים כך שאינך נעול על ספק אחד."}],"gaps":["השאלות נקטעו על ידי המנחה בגלל זמן (שאלה אחת אחרונה בלבד), והתמלול מסתיים בהכרזת הפסקת קפה  -  ייתכן שהיו שאלות נוספות שלא נקלטו. המספרים (77 אלף סשנים, ~4GB, אלף דולר בשבוע חישוב ל-DPO, עסקת Cursor וחסימת החשבון) מיוחסים לדובר ולא אומתו מקור חיצוני; התייחסותו ל-IPO של Anthropic היא הערת צד. במאגר הרשמי תיקיית talk-douglas-training-ai-on-your-own-code תואמת בתוכן לתמלול זה."],"source_refs":["https://www.youtube.com/watch?v=o-IunU6b1t8"]},{"number":4,"id":"KzhjnILSP0Y","url":"https://www.youtube.com/watch?v=KzhjnILSP0Y","type":"session","type_he":"סשן","duration":"26:42 דקות","title_he":"כשמנהל המוצר שלנו התחיל לכתוב קוד: מה שיעור המיזוג לימד אותנו על אימוץ AI","speaker_he":"תמוז דובנוב · Autonomy AI","summary":"תמוז טוען שהצוואר בקבוק הוא ההעברה בין תפקידים ולא כתיבת הקוד. הוא מזהיר מהוצאה גבוהה על AI בלי תוצאה, ומציע למדוד אימוץ לפי שיעור מיזוג של PR ממי שאינם מפתחים (מנהלי מוצר, מעצבים).","takeaways":["הדובר מציג שיעורי מיזוג ומידת התערבות מפתחים כמדדים לאימוץ. הנתונים הם מניסיונו, לא הבטחה לארגון אחר.","מודל עבודה: plan, merge, polish.","PR שנדחה: סוכן שמר תמונות בצורה שלא התאימה להחלטה ארכיטקטונית; לא מצפים ל-100% מיזוג.","בשאלות: מדדים, feature flags, rollback, ותיוג סיכון וגודל על PR כדי להפחית עייפות סקירה."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. הסיום נחתך באמצע שאלה בשאלות ותשובות.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"תמוז טוען שהצוואר בקבוק הוא ההעברה בין תפקידים ולא כתיבת הקוד. הוא מזהיר מהוצאה גבוהה על AI בלי תוצאה, ומציע למדוד אימוץ לפי שיעור מיזוג של PR ממי שאינם מפתחים (מנהלי מוצר, מעצבים).","chapters":[{"title":"פתיחה: מה זה בכלל \"AI-native\"?","body":"תמוז דובנוב, מייסד ו-CTO של AutonomyAI, פותח בסקר קהל: למי יש שיחות עם ה-CFO על הוצאות AI? למי יש PMs ומעצבים שפותחים PRs? וכמה מה-PRs האלה באמת ממוזגים? הוא טוען שכולם רוצים להיות \"AI-native\" אבל אף אחד לא יכול להגדיר מה זה  -  כולל \"רתמה\", הבאזוורד הנוכחי. התשובה החלקית שהוא שומע  -  \"PMs ומעצבים פותחים pull requests\"  -  היא לדעתו הסימפטום, לא ההגדרה.","points":["כולם רוצים AI-native אבל אף אחד לא מגדיר מה זה","PMs שפותחים PRs זה הסימפטום, לא המהות"],"kind":"idea"},{"title":"ההגדרה: מי שאכפת לו, יכול להחליט  -  ויכול לבצע","body":"ההגדרה של דובנוב: AI-native הוא כשהאדם שאכפת לו, שיש לו סמכות להחליט, הוא גם זה שיכול לבצע את העבודה. צוואר הבקבוק אף פעם לא היה כתיבת קוד אלא ההעברות: רעיון → פיגמה → שבוע דיונים → ספק → תור בבקלוג → ספרינט או שניים → ריוויו → איטרציות פיקסל-פרפקט. גם אם כותבים קוד מהר, פיצ'רים לא יוצאים מהר יותר. כשהופכים ל-AI-native, האדם שאכפת לו מבצע עם סוכנים כמעט מיד, מחזיר איטרציות על המקום, ורק כשהוא מרוצה שולח למפתח לריוויו  -  כלומר ריוויו עיצוב ומוצר מצומדים לפני שהמפתח בכלל שמע על הפיצ'ר. ימים ושבועות קורסים לדקות. ברמת הפרט כולם מקבלים שדרוג: PMs שאכפת להם מפיצ'רים ולא מספקים, מפתחים שאכפת להם מהמערכת, וסניורים שרוצים ארכיטקטורה ובעיות קשות. לדבריו אפשר לראות את זה גם בנתוני הגיוס: קצב גיוס מנהלי מוצר עולה מהר יותר ממפתחים  -  כי צוואר הבקבוק עבר למקבלי ההחלטות.","points":["AI-native = האדם שאכפת לו ומורשה להחליט גם מבצע","צוואר הבקבוק הוא ההעברות (handoffs), לא כתיבת הקוד","ריוויו עיצוב ומוצר נצמד לפני שהמפתח שומע על הפיצ'ר","כולם משודרגים לתפקיד שאכפת להם ממנו; גיוס PMs עולה מהר יותר ממפתחים (לדבריו)"],"kind":"idea"},{"title":"הדרכים הלא נכונות: לזרוק עוד מחשוב LLM","body":"דובנוב מזהיר שחלק עושים את זה לא נכון  -  וזה יקר מאוד. הוא מביא שלוש דוגמאות: אובר הגדילה את הוצאות ה-AI פי ששה מאז 2024 והתקציב השנתי נגמר תוך ארבעה חודשים; מיקרוסופט חילקה Claude Code לכולם ועכשיו לוקחת בחזרה; ומעמיק שבדק מעל 2,400 חברות מצא שלדבריו רק 18 דולר מכל 100 דולר על AI הולכים לקוד משמעותי שנשלח למשתמשים  -  השאר לריוורק ובאגים ש-AI ייצר, בלולאת בזבוז. שלוש הדרכים הלא נכונות: (1) לתת לימיטים גדולים לאותם מפתחים על אותן משימות  -  מפתח לא מעוניין במשימה ימסור אותה לסוכן שילולב ללא הפסקה וישרוף טוקנים, כי הוא לא מרגיש את העלות; (2) לתת ל-PMs ומעצבים כלי פרוטוטייפ  -  מאיץ פרוטוטייפים אבל לא פותר את צוואר הבקבוק של ההעברה; (3) לתת Claude Code ל-PMs ומעצבים  -  הם לא יודעים מה לעשות עם קוד, יבקשו עזרה בהקמת סביבה, ויפתחו PRs של אלפי שורות שרירותיות שמגדילים את עייפות ה-PR של הצוות.","points":["אובר: פי 6 הוצאות AI מאז 2024, התקציב אזל תוך 4 חודשים (לדבריו)","מיקרוסופט: חילקה Claude Code ולוקחת בחזרה (לדבריו)","רק $18 מכל $100 הולכים לקוד משמעותי (מחקר שהוא מצטט)","שלוש טעויות: לימיטים גדולים לאותם מפתחים, כלי פרוטוטייפ, Claude Code ללא-טכניים"],"kind":"idea"},{"title":"הדרך הנכונה: אותם כלים, משחק אחר","body":"שופיפיי לדבריו עושה את זה נכון: הפוקוס לא על לימיטים גבוהים למפתחים אלא על העצמת שאר הארגון  -  האנשים שיכולים להחליט בתחום שלהם מקבלים יכולת ביצוע בתחום שלהם. שופיפיי לקחה רישיונות Cursor ומדדה: 50% מהעבודה של הלא-טכניים מתקבלת כמו שהיא ומתמזגת בלי תיקוני מפתח, וסמנכ\"ל ההנדסה אומר שהקבוצות הצומחות הכי מהר הן לא המהנדסים. העקרון: same tools, different play  -  לתת לכל סוג משתמש כלי שמכוון אליו (Claude Code למפתחים; כלי כמו שלהם ל-PMs ומעצבים). ולשמור על ה-guards: ארגונים שקפצו מהר מדי מגלים בשיחות מכירה פיצ'רים שלא תואמים את המוצר  -  העקרונות ההנדסיים שנבנו שנים נעלמים. הוא מזכיר מתודולוגיה שהם מאמצים בשם plan, merge, polish לשמירה על משמרות תוך מהירות  -  אבל לא מספיק להעמיק.","points":["שופיפיי: 50% מעבודת הלא-טכניים מתמזגת כמו שהיא (לדבריו)","same tools, different play: כלי מותאם לכל סוג משתמש","לא לשחרר את ה-guards ההנדסיים גם כשזזים מהר; מתודולוגיית plan-merge-polish"],"kind":"idea"},{"title":"הרתמה: להפוך טעות לבלתי-אפשרית","body":"הביטחון לתת ללא-טכניים לגעת בקודבסיס מורכב מגיע מהרתמה. ההגדרה שלו: רתמה היא שראית את הסוכן טועה והפכת את אותה טעות לבלתי-אפשרית לחזור  -  קיר שנותן פידבק אוטומטי. והרתמה צריכה להסתגל: טעות נעשית, מזוהה, והרתמה גדלה אורגנית כלומר עם השימוש. העקרונות שהם מיישמים בהנדסת הרתמות: הסוכן צריך לעשות אונבורדינג עצמי לקודבסיס ולא להיות תלוי במפתח; להבין שפת מוצר ולתרגם אותה לקוד בלי שהמשתמש יצביע על קובץ ושורות; לנהל סשנים ארוכים עם קונטקסט טרי; לבדוק את עצמו בלולאות פידבק (אין גרוע מסוכן יתר-בטוח); לדעת מה זה \"טוב\"; וללמוד לא רק מסשן בודד אלא מכל המשתמשים במקביל כדי שהצמיחה תהיה מצטברת. למי שאומר \"הקוד שלי מסובך מדי\"  -  הוא עונה שמעולם לא נתקלו במקרה שלא עבד: מתמקדים בפרונט, מריצים סביבות מורכבות, מטפלים בסודות ובגישה לריפויים פרטיים.","points":["רתמה = טעות שהופכת לבלתי-אפשרית, עם פידבק אוטומטי  -  וגדלה אורגנית עם השימוש","עקרונות: אונבורדינג עצמי, שפת מוצר→קוד, סשנים ארוכים, בדיקה עצמית, למידה מכל המשתמשים","\"מעולם לא נתקלנו בקודבסיס שלא הצלחנו\"  -  גם מונוריפו מורכב וסודות (לדבריו)"],"kind":"idea"},{"title":"הקו בחול: מי רשאי לבצע מה","body":"יש קו ברור: אנשים שאכפת להם לא יכולים לבצע עבודה שאין להם סמכות אליה. מהנדסים שולטים בהחלטות ההנדסה והארכיטקטורה  -  בסיס נתונים, בקאנד; הלא-טכניים מתמקדים בשינויים פונים-משתמש: מיקרו-קופי, לייאאוט, פיצ'רים חדשים. זה נשמע פשוט אבל קשה  -  וצריך לצפות לכשלים. דוגמה מהחברה שלו: PM פתח PR של מעט מעל אלף שורות לפיצ'ר תמונות; הסוכן הצליח, ריוויו המוצר היה מושלם  -  והמפתח אמר \"לא ממזגים\", כי הסוכן שמר את התמונות בצד שרת בלי החלטת ארכיטקטורה, והמשתמש היה מגלה למחרת שהתמונות נעלמות. זה בריא: השיחה הארכיטקטונית פשוט הוזרזה; המפתח לקח את הבראנץ', שמר את כל הפרונט וה-UX, והחליף את הבקאנד. הציפייה היא לא 100% מיזוג  -  ולא לכעוס על המפתחים שעושים את תפקידם.","points":["קו בחול: לא-טכניים פונים-משתמש; מהנדסים  -  החלטות ארכיטקטורה ובקאנד","דוגמה: PR מוצלח מוצרית שנדחה בגלל החלטת אחסון server-side; המפתח שילב ושינה בקאנד","ציפייה ריאלית: לא 100% מיזוג; אחד מארבעה 'חורגים' זה בסדר"],"kind":"idea"},{"title":"איך מודדים: ספירת PRs, merge rate, ואחוז בלי נגיעת מפתח","body":"על בסיס מאות ארגונים ואלפי PRs בשבוע ובחודש, הם מודדים שלושה דברים. ראשית, ספירת PRs של לא-טכניים  -  ורצוי גם לפי אדם, כדי לוודא שכולם מועצמים ולא רק הבטוחים בעצמם. שנית, merge rate: בחברה שלהם, משתמש לא-טכני פותח בממוצע כ-50 PRs ברבעון ו-74% מתמזגים  -  כלומר אחד מארבעה חצה את הקו בטעות, וזו רמה ששומרת על אמון בין הפותחים לצוות הסוקר. שלישית, עומס נוסף: מודדים כמה מה-PRs הממוזגים התמזגו בלי שום התערבות מפתח  -  בלי קומיטים מתקנים; אצלם זה 84%. המוסר: AI-native הוא דמוקרטיזציה של יצירה  -  האדם האחראי והמורשה הוא גם המבצע, בלי להיות תלוי באחרים. וזה מה שגורם לפער בין \"משלמים יותר על AI\" לבין \"לא מרגישים מהר יותר\" להיסגר.","points":["מדד 1: ספירת PRs לא-טכניים (גם לפי אדם)","מדד 2: merge rate  -  אצלם 74% בממוצע (לדבריו)","מדד 3: 84% מהממוזגים בלי שום נגיעת מפתח (לדבריו)","המוסר: דמוקרטיזציה של יצירה  -  אחראי = מורשה = מבצע"],"kind":"idea"},{"title":"שאלות ותשובות","body":"ארבע שאלות נשאלו. ראשונה: איך בדיוק מודדים \"מיזוג בלי נגיעת מפתח\"? תשובה: המערכת שלהם רואה מי פתח את ה-PR בלוגים (עם טרייס של המשתמש), ובודקת את היסטוריית הקומיטים לפני המיזוג  -  אם הקומיט האחרון הוא של סוכן AutonomyAI ואף אחד לא דחף שינויי קוד (לא rebase בלבד), זה \"בלי נגיעה\". שנייה: האם התנועה היא גם הפוכה  -  מהנדסים נכנסים לשטח המוצר? תשובה: כן  -  מפתחים לא רוצים לחכות להחלטות מוצר, אז מפתחים מחליטים, הכול מאחורי feature flags (כדי למזג מהר בלי קונפליקטים), והאנשים שאכפת להם מה-UX פותחים PRs המשך לליטוש  -  פיצ'ר יכול לקבל 3-4 PRים וזה בסדר. שלישית: האם יש מנגנוני rollback אוטומטיים? תשובה: מסתמכים על ה-CI של הארגון; הסוכן לומד את הפרקטיקות של הקודבסיס (סטנדרטים, ספריית קומפוננטות)  -  ארגון עם feature flags יקבל feature flags אוטומטית; ארגון בלי טסטים  -  הסוכן לא יוסיף טסטים, והם שוקלים toggle שיכריח. רביעית: איך מויזואליזים עומס ריוויו על מפתחים? תשובה: הם מאמנים את הסוכן להוציא מעט שורות ולעשות reuse (כולל מידול גרף התלויות למציאת קומפוננטות קיימות), ובנוסף סוכן מתייג לכל PR רמת סיכון וגודל, וראשי צוותים מחלקים עומס לפי זה  -  במקום \"תשעה PRים זהים\" רואים \"שלושה קטנים בסיכון נמוך ואחד ענק\".","points":["מדידת 'בלי נגיעה': לוג היוצר + היסטוריית קומיטים לפני המיזוג","גם מהנדסים חוצים לשטח מוצר: feature flags + PRs המשך לליטוש","rollback: נשענים על ה-CI של הארגון; הסוכן מאמץ את פרקטיקות הקודבסיס (וגם את חסרונן)","ניהול עומס ריוויו: PRs קטנים + תיוג סיכון/גודל אוטומטי + חלוקת עומס"],"kind":"idea"},{"title":"איך מודדים בפועל 'מיזוג בלי נגיעת מפתח'?","body":"בודקים מי פתח את ה-PR בלוגים ואת היסטוריית הקומיטים לפני המיזוג: אם הקומיט האחרון של הסוכן ואין קומיטים מתקנים (לא rebase)  -  נספר כ'בלי נגיעה'.","kind":"qa"},{"title":"האם גם מהנדסים זזים לכיוון המוצר/UX?","body":"כן: מפתחים מקבלים החלטות מוצר, הכול מאחורי feature flags למיזוג מהיר, ואנשי המוצר/QA פותחים PRs המשך לליטוש (3-4 לפיצ'ר זה תקין).","kind":"qa"},{"title":"יש מנגנוני rollback אוטומטיים אם משהו פוצץ פרודקשן?","body":"נשענים על ה-CI של הארגון; הסוכן מאמץ את פרקטיקות הקודבסיס (feature flags אם קיימים; לא מוסיף טסטים אם זה לא הפרקטיקה  -  שוקלים toggle מכריח).","kind":"qa"},{"title":"איך מנהלים ומציגים את עומס הריוויו על מפתחים?","body":"מאמנים את הסוכן ל-PRs קטנים עם reuse; סוכן מתייג לכל PR גודל ורמת סיכון; ראשי צוותים מחלקים עומס בהתאם.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["AI-native הוא לא 'יותר טוקנים' אלא דמוקרטיזציה של יצירה: מי שאכפת לו ויש לו סמכות  -  גם מבצע.","צוואר הבקבוק הוא ההעברות, ולא כתיבת קוד; לזרוק עוד מחשוב LLM על אותם תהליכים שורף כסף (הדוגמאות של אובר ומיקרוסופט).","הביטחון לתת ללא-טכניים לגעת בקוד מגיע מרתמה שמתאימה למשתמש, הופכת טעויות לבלתי-אפשריות, ולומדת מכל המשתמשים.","מודדים אימוץ בשלושה מדדים: ספירת PRs, merge rate (~74%), ואחוז ממוזגים בלי נגיעת מפתח (~84%)  -  תוך שמירה על קו בחול בין UX לארכיטקטורה."],"kind":"idea"}],"diagram":{"title":"המודל של דובנוב: קריסת ההעברות ומשפך המדדים","structure":"שני חלקים: למעלה  -  ציר 'לפני/אחרי': שרשרת ההעברות הארוכה (רעיון→פיגמה→ספק→ספרינט→ריוויו) מתכווצת ל'מי שאכפת לו מבצע עם סוכן → ריוויו מפתח'. למטה  -  משפך מדדים: PRs שנפתחו → 74% ממוזגים → 84% בלי נגיעת מפתח, כשהרתמה מקיפה את התהליך ולומדת מטעויות.","nodes":[{"id":"handoffs","label":"צוואר בקבוק ישן: רעיון→עיצוב→מפרט→בקלוג→ריוויו→איטרציות"},{"id":"collapse","label":"AI-native: אכפת לי = אני מחליט = אני מבצע (עם סוכן)"},{"id":"harness","label":"רתמה: טעות → בלתי-אפשרית; לומדת מכל המשתמשים"},{"id":"line","label":"קו בחול: UX ללא-טכניים | ארכיטקטורה למהנדסים"},{"id":"funnel","label":"מדדים: ספירת PRs → merge rate (74%) → בלי נגיעת מפתח (84%)"}],"edges":[{"from":"handoffs","to":"collapse","label":"ימים ושבועות → דקות"},{"from":"harness","to":"collapse","label":"נותן ביטחון לגעת בקוד"},{"from":"collapse","to":"line","label":"מחולק לפי סמכות"},{"from":"line","to":"funnel","label":"נמדד במיזוגים"}]},"terms":[{"term":"AI-native","definition":"לפי דובנוב: ארגון שבו האדם שאכפת לו ויש לו סמכות להחליט הוא גם זה שמבצע את העבודה בעזרת סוכנים."},{"term":"Handoff","definition":"ההעברה בין תפקידים (רעיון→עיצוב→מפרט→פיתוח→ריוויו)  -  צוואר הבקבוק האמיתי של מהירות הפיצ'רים."},{"term":"PR fatigue","definition":"עייפות צוות הפיתוח מביקורת על עוד ועוד PRs  -  במיוחד PRs רועשים או ענקיים."},{"term":"Plan, Merge, Polish","definition":"מתודולוגיית עבודה שהארגון שלו מאמץ לשמירה על איכות ומהירות מיזוג בלי קונפליקטים  -  מוזכרת בקצרה בלבד."},{"term":"רתמה (Harness)","definition":"לפי דובנוב: מנגנון שהופך טעות שזוהתה אצל הסוכן לבלתי-אפשרית לחזור, עם פידבק אוטומטי, ומתפתח עם השימוש."},{"term":"למידה מקבילה מכל המשתמשים","definition":"שיפור הרתמה מכל הסשנים של כל המשתמשים יחד  -  צמיחה מצטברת ולא מקומית."},{"term":"Merge rate","definition":"אחוז ה-PRs שנמזגים מתוך אלו שנפתחו; המדד המרכזי לאימוץ בריא לדבריו."},{"term":"מיזוג בלי נגיעת מפתח","definition":"PR שהתמזג בלי קומיטים מתקנים ממפתח  -  מדד לעומס שהארגון לא מוסיף על צוות הפיתוח."}],"gaps":["השאלות נקטעו בגלל הזמן (המנחה סגר את המקטע אחרי ארבע שאלות). המספרים  -  Uber פי 6, מיקרוסופט, $18 מכל $100, שופיפיי 50%, 74% ו-84%  -  מובאים כדברי הדובר או מחקרים שהוא מצטט, ולא אומתו מקור חיצוני. מתודולוגיית plan-merge-polish הוזכרה אבל לא הורחבה בגלל הזמן. המוצר של החברה שלו הוזכר בשם AutonomyAI/'Tanya' בתמלול האוטומטי (ייתכן עיוות תמלול)."],"source_refs":["https://www.youtube.com/watch?v=KzhjnILSP0Y"]},{"number":5,"id":"guhTp2Q8VX0","url":"https://www.youtube.com/watch?v=guhTp2Q8VX0","type":"session","type_he":"סשן","duration":"30:39 דקות","title_he":"בנצ'מרק לעידן הסוכנים: מדידת ביצועים מעבר ל-LLM","speaker_he":"אמיט קושווהא · NVIDIA","summary":"עומסי סוכנים שונים מצ'אט: הרבה סבבים, הקשר גדל, וקריאות כלים. אמית מסביר prefix caching, ניתוב מודע ל-KV cache ו-speculative decoding, מדוע בנצ'מרקים קיימים לא משקפים עומס כזה, ואיך למדוד נכון, כולל בנצ'מרק הסוכנים של Artificial Analysis.","takeaways":["Prefix caching ו-KV-cache-aware routing חיוניים כי ההקשר חוזר בכל סבב.","Speculative decoding: כ-3 טוקנים לכל מעבר, לדבריו.","להסתכל על התפלגויות (P25 מול P95) ולא על ממוצע.","GPU נשאר סרק בזמן קריאות כלים על CPU, וצריך למדוד במצב יציב.","פערים שהוא ציין: מספר סוכנים, סשנים ארוכים ועומסים הטרוגניים."],"category":"עלות וביצועים","coverage":"כל התמליל הזמין נסקר. השאלה האחרונה בשאלות ותשובות נחתכה ('Is it ki...').","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"עומסי סוכנים שונים מצ'אט: הרבה סבבים, הקשר גדל, וקריאות כלים. אמית מסביר prefix caching, ניתוב מודע ל-KV cache ו-speculative decoding, מדוע בנצ'מרקים קיימים לא משקפים עומס כזה, ואיך למדוד נכון, כולל בנצ'מרק הסוכנים של Artificial Analysis.","chapters":[{"title":"פתיחה: הבנצ'מרקים לא עקבו אחרי הסוכנים","body":"אמית קושוואה, ארכיטקט פתרונות ראשי ב-NVIDIA במחלקת Deep Learning Solutions, פותח בבעיה: הבנצ'מרקים שאמורים לשקף עומסי עבודה מהעולם האמיתי השתנו בשנה וחצי האחרונות  -  מצ'אטבוטים פשוטים לסוכנים  -  אבל הבנצ'מרקים לא התעדכנו. הוא מציג שלושה נושאים: איך נראה עומס עבודה של סוכן, אילו אופטימיזציות כבר קיימות להרצה יעילה שלו, ומה הבנצ'מרקים הנוכחיים מפספסים  -  ומסיים בדוגמה לבנצ'מרק שמנסה לגשר על הפער ובמה שעוד חסר.","points":["העומסים השתנו מצ'אטבוט חד-תורי לסוכנים מורכבים; הבנצ'מרקים נשארו מאחור","שלושה חלקים: העומס האג'נטי, אופטימיזציות קיימות, מה מפספסים"],"kind":"idea"},{"title":"איך נראה עומס עבודה אג'נטי","body":"בעידן הצ'אטבוט הישן רוב השיחות היו חד-תוריות: קלט קצר (1K-4K טוקנים), פלט קצר, בלי כלים. בעומס אג'נטי הכול מתפוצץ: עשרות קריאות כלים, ה-LLM נקרא שוב ושוב, אורכי קונטקסט של עשרות עד מאות אלפי טוקנים, ופלטים של מאות עד אלפי טוקנים. הדוגמה שלו: משתמש מבקש לתקן טסט רענן (flaky) בקודבסיס. ה-LLM עונה \"לך תבדוק קובץ מסוים\", רץ כלי (bash, grep, חיפוש ווב), התוצאה חוזרת ל-LLM, והוא שולח לכלי הבא  -  טרג'קטוריה שיכולה להימשך 20 עד 40 תורות. נקודות חשובות: רוב הטוקנים נוצרים בצד הקלט  -  הקריאה של קבצים והזנה חזרה; טוקני הפלט קטנים יחסית כי ה-LLM רק מנחה איזה כלי להפעיל. והעומס מעורב: החלקים שה-LLM רץ הם על GPU, והכלים רצים בדרך כלל על CPU. ההרצאה מתמקדת בסוכני קוד, אבל עומסים אחרים נראים אחרת.","points":["צ'אטבוט ישן: חד-תורי, קונטקסט קטן, בלי כלים; סוכן: עשרות קריאות כלי, קונטקסט עצום","טרג'קטוריית 'תקן טסט רענן': LLM→כלי→LLM×20-40","רוב הטוקנים בצד הקלט (קריאת קבצים); הפלט קטן  -  הוראות לכלים","עומס מעורב: LLM על GPU, כלים על CPU"],"kind":"idea"},{"title":"שלוש אופטימיזציות יסוד: caching, routing, speculative decoding","body":"האופטימיזציה הראשונה היא prefix caching: עד התור ה-40 נצבר קונטקסט ענק, אבל אם שומרים בקאש את מה שכבר חושב, מחשבים רק את הטוקנים החדשים  -  בלי זה נפגעים ה-TTFT והביצועים. הקאש הוא מטריצות ה-K/V, דרך המודל לאחסן היסטוריה. הבעיה: כשמגישים את המודל על כמה רפליקות, תור שמנותב ב-round robin עלול לנחות על רפליקה בלי הקאש  -  ולכן נדרשת ניתוב מודע-קאש (KV cache-aware routing): לוודא שכל התורות של סשן נוחתים על אותה רפליקה, למשל דרך מזהה סשן. האופטימיזציה השלישית היא speculative decoding בצד ה-decode: מודל טיוטה קטן ומהיר מנבא ארבעה טוקנים קדימה, והמודל הגדול רק מאמת אותם בבקשה אחת  -  שלושה טוקנים במעבר אחד. יש וריאציות: לאמן מודל טיוטה מהדאטה של הגדול, או multi-token prediction שמובנה כבר במודלים חדשים ופשוט מדליקים אותו.","points":["prefix caching: מחשבים רק טוקנים חדשים  -  הלחם והחמאה של עומסים אג'נטיים","KV cache-aware routing: כל תורות הסשן חייבים לנחות על אותה רפליקה","speculative decoding: מודל טיוטה קטן מנבא, הגדול מאמת במעבר אחד; MTP מובנה במודלים חדשים"],"kind":"idea"},{"title":"מה הבנצ'מרקים הקיימים מפספסים","body":"מול זה, הבנצ'מרקים הנוכחיים מודדים משהו אחר לגמרי: צורות קבועות (input/output קבועים), בלי קריאות כלי, עם האופטימיזציות כבויות, ובתור בודד. בעולם האמיתי עץ הפרויקט גדל כל הזמן  -  הקונטקסט נאסף מכלים ומתנפח  -  אז צורה קבועה מפספסת את המהות; אין רב-תוריות; והאופטימיזציות שהופכות את העומס לבר-הרצה בכלל לא נמדדות. המסקנה: הביצועים שנמדדים היום לא מייצגים את העומס האמיתי.","points":["בנצ'מרקים קלאסיים: צורות קבועות, בלי כלים, בלי רב-תור, אופטימיזציות כבויות","בעומס אמיתי עץ הפרויקט והקונטקסט גדלים כל הזמן  -  'fixed shape' מפספס את העיקר"],"kind":"idea"},{"title":"למדוד נכון: התפלגויות ופרסנטילים, לא ממוצעים","body":"בעומסים אג'נטיים אי אפשר לדבר על ממוצע וחציון  -  חייבים התפלגויות. הוא מציג היסטוגרמות של TTFT (שמאל טוב  -  תגובה מהירה) ושל מהירות טוקנים (ימין טוב  -  ייצור מהיר). חוויית המשתמש מתה בזנבות: צריך לחתוך את ה-P95 כך שיתאים לציפיות הלקוח (P95 = 95% מהבקשות מהירות מהערך). והנה המלכודת: בהשוואה של speculative decoding דולק מול כבוי, ההתפלגות הירוקה (דולק) מהירה בהרבה ברוב הבקשות  -  אבל במדד P5 היא נראית גרוע יותר! במקרה שלהם התשובה הייתה למדוד P25 ולא P5, כי אחרת מענישים אופטימיזציה מצוינת על ארטיפקט שלה. המסר: צריך להתעמק במה שכל אופטימיזציה עושה להתפלגות ולהתאים מדד לציפיית הלקוח  -  לא מדד אחד פשטני.","points":["חייבים התפלגויות ופרסנטילים (P25/P95), לא ממוצע/חציון","חוויית משתמש נקבעת בזנבות ההתפלגות","מלכודת: speculative decoding נראה גרוע ב-P5 אבל מעולה ברוב הבקשות  -  אצלם עברו ל-P25"],"kind":"idea"},{"title":"כלים משנים את הקונקורנציה: ה-GPU לא תמיד עובד","body":"אם מתעלמים מקריאות הכלי, גם חישוב הקונקורנציה שגוי. בתמונה בלי כלים, ארבעה משתמשים \"אורזים\" את ה-GPU בצפיפות מלאה. במציאות, אחרי כל קריאת LLM רץ כלי על ה-CPU  -  ובזמן הזה ה-GPU בטל. אם קריאת כלי אורכת שניהיה כמו קריאת מודל, אפשר לתמוך בפי שניים משתמשים מאשר חשבתם, כי חלק גדול מהעומס הוא CPU. לכן כשמודדים כמה משתמשים חומרה יכולה לשאת, חייבים לייצג את הטרג'קטוריות האמיתיות כולל האזורים האפורים של ה-CPU.","points":["בלי כלים נראה שה-GPU עמוס תמיד; עם כלים הוא בטל חלק מהזמן","קריאת כלי באורך קריאת מודל ≈ כפילות משתמשים נתמכים (בדוגמה שלו)","מדידת קונקורנציה חייבת לשקף טרג'קטוריות אמיתיות GPU+CPU"],"kind":"idea"},{"title":"מצב יציב: אל תמדדו לפני שהקאש התחמם","body":"עוד מלכודת עדינה: מדדים לוקחים זמן להתייצב. בתחילת הריצה הקאש ריק והמערכת במצב מעבר  -  אם מודדים שם TTFT של 10 שניות ומכריזים שהפריסה כשלה ביחס ל-SLO, טועים: צריך לתת למדדים להתיישב ולראות שהעקומה שטחה בסוף. אותו סיפור למהירות טוקנים: מי שמודד מוקדם יחשוב שהפריסה גרועה ויוסיף חומרה שלא לצורך; מי שממתין ליציבות רואה פריסה תקינה שעומדת בשני ה-SLOs.","points":["מדדים במצב מעבר מטעים  -  לחכות לשטח בעקומה","מדידה מוקדמת עלולה להוביל להחלטת חומרה מיותרת"],"kind":"idea"},{"title":"בנצ'מרק שמנסה לגשר: artificial analysis","body":"כדוגמה לבנצ'מרק שמגשר על הפער הוא מציג בנצ'מרק חדש (יצא שבועות ספורים לפני הכנס, התוצאות עוד לא פורסמו) של חברת הבנצ'מרקים הצד-שלישי Artificial Analysis: הוא כולל KV cache-aware routing ברב-דיירות, speculative decoding, מבוסס SLO, לשני מודלים (DeepSeek ו-GPT-OSS 120B בשלב זה) ועם דאטהסט טרג'קטוריות רב-דיירות אמיתי. השאלה שהוא עונה עליה: בהינתן SLO (מהירות טוקנים ו-TTFT נדרשים), כמה משתמשים חומרה נתונה יכולה להחזיק?  -  ויוצגו גם מדדי עלות-לדולר.","points":["בנצ'מרק Artificial Analysis: routing מודע-קאש, speculative decoding, SLO-based, דאטה אמיתי","השאלה: כמה משתמשים חומרה מסוימת מחזיקה תחת SLO; גם מדדי עלות"],"kind":"idea"},{"title":"מה עוד חסר בשדה הבנצ'מרקים","body":"לסיכום: טרג'קטוריות רב-תוריות, שלוש האופטימיזציות, מדידה בהתפלגויות ופרסנטילים, שילוב כלים בקונקורנציה, ומדידה רק במצב יציב. אבל זה רק הבור ולחם. מה שחסר: זרימות רב-סוכניות (איך בכלל מבצ'מקים כמה סוכנים שמתקשרים?); צימוד איכות לביצועים  -  כי מהירות בלי פתרון נכון של המשימה חסרת משמעות; סשנים ארוכים של ימים (הקאש גדל כל הזמן  -  איך מנהלים את הזיכרון?); ועומסים הטרוגניים שבהם GPU ו-CPU צמודים, ומדדים אחרים כמו זמן השלמת משימה. הבנצ'מרקים התעדכנו לעידן הצ'אטבוט; לעידן הסוכנים הם רק נבנים עכשיו.","points":["חסר: בנצ'מרקים רב-סוכניים, צימוד איכות×ביצועים, סשנים של ימים, עומסים הטרוגניים GPU/CPU","הבנצ'מרקים היום שייכים לעידן הצ'אטבוט; לסוכנים רק מתחילים"],"kind":"idea"},{"title":"שאלות ותשובות","body":"שאלה ראשונה: האם speculative decoding עובד בטמפרטורה לא-אפס, או שהבנצ'מרק מניח אפס? תשובה: עובד גם בטמפרטורה לא-אפס  -  גם אז דגימה היא מהתפלגות, וכל עוד התפלגות מודל הטיוטה תואמת את של הגדול, יש הסתברות גבוהה לנבא נכון את מה שהמודל הגדול היה מייצר. שאלה שנייה: ההיסטוגרמות של TTFT ומהירות  -  על אותה טרג'קטוריה אחת או על כל הסוויטה? תשובה: על מאות-אלפי טרג'קטוריות שנאספו ורצות על החומרה. בתגובה להערת שואל (בעיה קשה מאריכה TTFT) הוא הבהיר ש-TTFT נמדד לבקשה בודדת בשרשרת, ושבגלל prefix caching ה-TTFT תלוי רק בחלק החדש  -  ואם כלי החזיר תשובה ארוכה במיוחד, בלי קאש ה-TTFT יקפוץ, ולכן הקאש הוא הלחם והחמאה.","points":["speculative decoding עובד גם בטמפרטורה > 0 (דגימה מהתפלגות תואמת)","ההיסטוגרמות נאספות ממאות-אלפי טרג'קטוריות, לא פרומפט אחד","TTFT נמדד לכל בקשה בשרשרת; הקאש שומר אותו קטן גם אחרי תשובות כלי ארוכות"],"kind":"idea"},{"title":"האם speculative decoding עובד בטמפרטורה לא-אפס?","body":"כן  -  גם אז דגימה היא מהתפלגות; כל עוד התפלגות מודל הטיוטה תואמת את הגדול, הסיכוי לנבא נכון גבוה.","kind":"qa"},{"title":"ההיסטוגרמות של TTFT ומהירות הן על אותו פרומפט או על כל הסוויטה?","body":"על מאות-אלפי טרג'קטוריות שנאספו ורצות על החומרה; TTFT נמדד לכל בקשה בשרשרת, והקאש שומר אותו קטן גם אחרי תשובות כלי ארוכות.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["עומס אג'נטי שונה מהותית מצ'אטבוט: טרג'קטוריות של עשרות תורות, קונטקסט עצום בצד הקלט, פלט קטן, ושילוב GPU/CPU.","שלוש אופטימיזציות הן יסוד: prefix caching, KV cache-aware routing ו-speculative decoding  -  ובנצ'מרקים נוכחיים כמעט לא מודדים אותן.","מדידה נכונה דורשת התפלגויות ופרסנטילים מתאימים (לא ממוצעים), הכנסת זמני הכלי לחישוב הקונקורנציה, והמתנה למצב יציב.","בנצ'מרקים כמו של Artificial Analysis מתחילים לגשר על הפער, אבל רב-סוכניות, צימוד איכות וסשנים ארוכים עוד פתוחים."],"kind":"idea"}],"diagram":{"title":"העומס האג'נטי של קושוואה: טרג'קטוריה, שלוש אופטימיזציות ומדידה נכונה","structure":"במרכז  -  טרג'קטוריית סוכן חוזרת: קלט משתמש → [LLM (GPU) → כלי (CPU)]×20-40 → תשובה. סביבה שלוש האופטימיזציות (prefix caching, KV cache-aware routing, speculative decoding) ומתחת שלוש מלכודות המדידה (פרסנטילים, קונקורנציית כלים, מצב יציב).","nodes":[{"id":"user","label":"קלט משתמש יחיד (למשל: תקן טסט רענן)"},{"id":"llm","label":"LLM על GPU  -  פלט קטן: איזה כלי להפעיל"},{"id":"tool","label":"כלי על CPU  -  קורא קבצים, מזין קונטקסט חזרה (רוב הטוקנים)"},{"id":"cache","label":"prefix caching + routing מודע-קאש לאותה רפליקה"},{"id":"spec","label":"speculative decoding  -  3 טוקנים במעבר אחד"},{"id":"metrics","label":"מדידה: התפלגויות P25/P95, קונקורנציית GPU/CPU, רק במצב יציב"}],"edges":[{"from":"user","to":"llm","label":"שאלה"},{"from":"llm","to":"tool","label":"הוראת כלי (×20-40)"},{"from":"tool","to":"llm","label":"תוכן קבצים חזרה"},{"from":"cache","to":"llm","label":"מחשב רק טוקנים חדשים"},{"from":"spec","to":"llm","label":"טיוטה→אימות"},{"from":"metrics","to":"llm","label":"מודדים נכון או מטעים"}]},"terms":[{"term":"טרג'קטוריה (Trajectory)","definition":"רצף התורות של סוכן: קלט משתמש אחד שמוביל ל-20-40 קריאות LLM וכלים."},{"term":"TTFT (Time To First Token)","definition":"כמה מהר חוזר הטוקן הראשון מהמודל; אחד המדדים המרכזיים."},{"term":"Prefix caching","definition":"שמירת חישובי ה-prefill בקאש כך שבתור הבא מחשבים רק את הטוקנים החדשים."},{"term":"KV cache-aware routing","definition":"ניתוב בקשות לרפליקה שמחזיקה את ה-KV cache של הסשן  -  דרך מזהה סשן או לוגיקת קאש."},{"term":"Speculative decoding","definition":"מודל טיוטה קטן מציע כמה טוקנים, המודל הגדול מאמת בבת אחת  -  האצת פלט; MTP הוא וריאנט מובנה."},{"term":"P95 / P25","definition":"P95: 95% מהבקשות טובות מהערך. בחירת הפרסנטיל הנכון קריטית כדי לא לשפוט אופטימיזציות באופן שגוי."},{"term":"מצב יציב (Steady state)","definition":"המצב שאחרי חימום הקאשים, שבו המדדים מייצגים את הפריסה באמת; מודדים רק שם."},{"term":"SLO","definition":"יעד רמת שירות (TTFT, מהירות טוקנים); הבנצ'מרק בודק קונקורנציה מקסימלית תחת היעד."}],"gaps":["השאלות נקטעו על ידי המנחה (\"אנחנו בחוסר זמן\")  -  שואלים נוספים הופנו לדוכן. שמות המודלים בבנצ'מרק ('deep before', 'GPT us 120') עולים מעורפלים בתמלול (כנראה DeepSeek ו-GPT-OSS 120B) ולא אומתו. המספרים (20-40 תורות, פי 2 קונקורנציה) הם דוגמאות של הדובר, לא נורמה מחייבת."],"source_refs":["https://www.youtube.com/watch?v=guhTp2Q8VX0"]},{"number":6,"id":"tFffUnSq7VA","url":"https://www.youtube.com/watch?v=tFffUnSq7VA","type":"session","type_he":"סשן","duration":"42:02 דקות","title_he":"מצב העניינים: עוזרי קידוד של AI","speaker_he":"בירגיטה בקלר · Thoughtworks","summary":"בריגיטה מסכמת את מצב עוזרי הקידוד: מודלים (לא קסם, חסרי מצב, הקשר מול קשב, התאמה למשימה), מעטפת הסוכן והנדסת הקשר, 'מכווני דרך' (guides) ו'חיישנים' (sensors), ואחר כך העלויות: אבטחה, יציבות, שינוי, טוקנים, עומס קוגניטיבי, משבר סקירה וקריסת זרימה. היא מציעה מודל סיכון להחלטה כמה פיקוח להפעיל.","takeaways":["מודלים מקומיים (Qwen 3.6, Gemma 4) כהדגמה להבדלים בין מודלים.","Guides לפני ו-sensors אחרי; חישוביים מול אינפרנציאליים.","כשסוכן טועה: לבנות פתרון קבוע (Hashimoto), למשל כלל lint במקום הוראה ב-AGENTS.md.","חיישנים בזמנים שונים, כולל 'garbage collection' מחזורי.","סיכון = סבירות, השפעה ויכולת לזהות. 'Cognitive surrender': על מה אנחנו מוותרים."],"category":"הקשר וזיכרון","coverage":"כל התמליל הזמין נסקר. הכתוביות מגיעות למוזיקה הסוגרת, סביב 41:50 מתוך 42:02 דקות.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"בריגיטה מסכמת את מצב עוזרי הקידוד: מודלים (לא קסם, חסרי מצב, הקשר מול קשב, התאמה למשימה), מעטפת הסוכן והנדסת הקשר, 'מכווני דרך' (guides) ו'חיישנים' (sensors), ואחר כך העלויות: אבטחה, יציבות, שינוי, טוקנים, עומס קוגניטיבי, משבר סקירה וקריסת זרימה. היא מציעה מודל סיכון להחלטה כמה פיקוח להפעיל.","chapters":[{"title":"פתיחה: לראות את היער על העצים","body":"בירגיטה בוקלר, Distinguished Engineer ב-ThoughtWorks, סוגרת את הכנס. היא מתארת את תפקידה: לעקוב אחרי התחום עבור הצוותים והלקוחות ולכתוב על כך (בין השאר באתר של מרטין פאולר). משימתה: לעזור לראות את היער על עצים  -  ריקפ של מה ששמעתם ביומיים, וגם של 12 החודשים האחרונים: ההתקדמות, הדברים שהולכים פחות טוב, וההשלכות מסדר שני  -  כדי שמחר, כשעמית ישאל \"אז מה כדאי לי לדעת?\", תהיה לכם תשובה.","points":["מטרה: ריקפ של הכנס ושל 12 החודשים, כולל תופעות לוואי מסדר שני","המודלים עצמם לא החלק הכי מעניין בעיניה  -  האקוסיסטם סביבם כן"],"kind":"idea"},{"title":"מה חובה לדעת על מודלים","body":"ארבעה דברים בסיסיים. ראשית, הם לא קסם  -  מתמטיקה מרשימה ומועילה מאוד, אבל קל ליפול למלכודת לחשוב שהם יותר מזה. שנית, הם חסרי מצב: למודל אין סשן; בכל תור הרתמה שולחת את כל ההיסטוריה מחדש (עם אופטימיזציות קאשינג), וזה משפיע ככל שהשיחה מתארכת. שלישית, גודל חלון הקונטקסט מול הקשב: החלונות גדלו, אבל יש טרייד-אוף ביכולת של המודל לשמור קשב על כל ההוראות והקונטקסט שדוחפים. רביעית והכי חשוב  -  איזה מודל לאיזו משימה: אוטוקומפליט, שינוי קבצים מוגדרים, שינוי מורכב שדורש מחקר קוד, או תכנון ודיבוג עם הרבה שאלות ושיקולים  -  כל משימה דורשת רמת חשיבה, קונטקסט וקריאות כלי אחרת. כאן לא צריך לדעת כל פיצ'ר של מודל אלא להתאמן ברפלקציה על סוגי המשימות: כמה קבצים, מה רדיוס הפגיעה, כמה אי-ודאות יש.","points":["המודלים לא קסם  -  מתמטיקה מרשימה, לא יותר","חסרי מצב: כל ההיסטוריה נשלחת מחדש בכל תור","חלון גדול ≠ קשב טוב על הכול","הכי חשוב: רפלקציה על סוג המשימה והתאמת רמת הכוח של המודל"],"kind":"idea"},{"title":"מודלים קטנים על הלפטופ: מה כבר אפשר","body":"תרגיל מומלץ: מי ש\"רחץ במודלים חזקים\" כבר שכח מה מקבל כמובן מאליו. היא מדגימה Qwen 3.6 על MacBook M3 עם 48GB זיכרון  -  לא בהרבה איטי יותר מ-Sonnet או Opus ב-Claude Code (ב-OpenCode). אבל tool calling  -  קריטי לזרימות אג'נטיות  -  עדיין מתקשה אפילו במודל שהמכונה שלה בקושי הריצה. מצד שני, Gemma 4 (מודל קטן שמדברים עליו הרבה) ביצע מצוין משימה שהיא ידעה בדיוק מה לבקש: פסקה אחת של הוראות, ריפקטורינג קצר  -  ונוצר סקריפט שירות. המסקנה חוזרת: להכיר את סוג המשימה ולמפות אותה לרמת הכוח הנדרשת.","points":["מודלים קטנים השתפרו מאוד במהירות; tool calling עדיין נקודה חלשה","משימה מוגדרת היטב מתאימה למודל קטן מקומי (Gemma 4 בדוגמה)"],"kind":"idea"},{"title":"הרתמה (Coding Harness): מה יש מתחת למכסה","body":"סביב המודל יושבת הרתמה  -  מה שפעם קראו לו סוכן קוד. מתחת למכסה: system prompt והוראות שבדרך כלל לא רואים (אלא אם קוד פתוח), אינטגרציות כלים סטנדרטיות (עריכת קבצים, קריאה, חיפוש קוד), אורקסטרציה (סאב-סוכנים, כמה קריאות במקביל), לפעמים קאשינג, ממשק (טרמינל או IDE), ורמות שונות של הרחבה ותצפיתיות (ה-sok של pi coding agent מפורסם בגמישותו). כבר נשמעות טענות \"בלוט\": כמו Spring פעם, גם Claude Code תוך שנה מרגיש כבד. היא מדגימה השוואה של מה שנטען כבר בפתיחת סשן ב-pi מול Codex מול Claude Code. הלקח: צריך להבין את הפיצ'רים וההבדלים ולא להתבלבל מהממשק  -  כשהיא ראתה אנשים מסיקים ש\"טרמינל זה הסיבה ש-Claude Code טוב\", בעוד Cursor חזק באותה מידה מתחת למכסה.","points":["רתמה = פרומפטים, כלים, אורקסטרציה, UI, הרחבה ותצפיתיות","מחזור הבלוט של תוכנה הגיע גם לסוכנים  -  תוך פחות משנה","לא לבלבל ממשק עם איכות: טרמינל הוא לא הסיבה שכלי טוב"],"kind":"idea"},{"title":"הנדסת הרתמה = הנדסת קונטקסט: מדריכים וחיישנים","body":"המודל המנטלי שלה להנדסת רתמה (שהיא מעדיפה לקרוא לו הנדסת קונטקסט לסוכני קוד  -  המונח עוד מתגבש): מצד אחד \"מדריכים\" (guides) בפיד-פורוורד  -  קבצי markdown עם קונבנציות (נורמטיבי), קונטקסט מוצרי (אינפורמטיבי) והוראות עבודה, בין שישבים בסביבה ובין שנטענים דינמית דרך סקילס; מנסים לצפות מה הסוכן עלול לטעות ומה רוצים שיעשה. מצד שני \"חיישנים\" (sensors) בפידבק  -  כדי שהסוכן יתקן את עצמו לפני שאנחנו רואים את הקוד: סוכני ריוויו (אינפרנציאלי, LLM שופט LLM), אבל גם כלים חישוביים מהעולם שלפני ה-AI (ניתוח סטטי, לוגים, דפדפן). באותו שיבוץ יש גם מדריכים חישוביים: code mods כמו OpenRewrite לשדרוגי גרסאות  -  הכותרות של אמזון על חיסכון במאות שנות-מפתח היו בעיקר code mods שנתנו ל-AI  -  או חיפוש קוד טוב יותר לקודבסיס ענק. ההבחנה אינפרנציאלי (GPU) מול חישובי (CPU) חוזרת בשני הצדדים.","points":["מדריכים (feed forward): נורמטיבי, אינפורמטיבי, הוראות  -  סטטי או דינמי (סקילס)","חיישנים (feedback): סוכני ריוויו אינפרנציאליים מול כלים חישוביים (סטטי, לוגים, דפדפן)","מדריכים חישוביים: code mods (OpenRewrite)  -  מאחורי סיפור שדרוגי ה-Java של אמזון"],"kind":"idea"},{"title":"איפה לשים חיישנים, ואיך מתכנתים את הסביבה","body":"כפי שאמר מיטשל האשימוטו (היא מצטטת את הפוסט שלו): כל פעם שהסוכן טועה, מנתחים פתרון כך שלא יטעה שוב  -  ו-AI עוזר לבנות את הפתרונות. שתי דוגמאות: במקום \"אל תשתמש ב-console.log\" ב-AGENTS.md (שחוזר בכל ריצה), חוק lint עם הודעה מותאמת שמפנה ללוגר המותאם  -  יעיל במיוחד לטעויות נדירות. ובמקום סקיל שמסביר על שכבות הבקאנד, כלי סריקת imports בשפת התכנות שתופס הפרות מודולריות כבר בהתחלה. איפה לשים חיישנים: לפני קומיט אם זה זול ומהיר (היא מודה ש-80% מהקומיטים שלה ישר ל-main), ב-PR חיישנים אינפרנציאליים נוספים, ב-CI בעיקר חיישנים חישוביים  -  לא רוצים שהאדום/ירוק יהיה תלוי בפרשנות סמנטית של LLM  -  ובנוסף \"איסוף זבל\" (כפי שהצוות של OpenAI קרא לזה בהרצאה אתמול): זיהוי סחף רציף של חוב טכני  -  סקירת מודולריות, טריות תלויות, אבטחה  -  פעם בשבוע, עם תהליך צוותי איך מתמודדים עם ממצאים (בדומה לפרצות אבטחה). ובפרודקשן: חיישנים ל-fitness ארכיטקטוני  -  סקיילביליות, לטנסי  -  דרך נתוני תצפיתיות.","points":["כל טעות סוכן → מהנדסים פתרון שלא תחזור (ציטוט האשימוטו)","לינט מותאם > הוראה ב-AGENTS.md לטעויות נדירות; כלי imports > סקיל על שכבות","מפה: pre-commit (זול) → PR (אינפרנציאלי) → CI (חישובי בלבד) → 'איסוף זבל' שבועי → חיישני פרודקשן"],"kind":"idea"},{"title":"12 חודשים בדיעבד: מאוטוקומפליט לנחילים","body":"היא סוקרת את ציר הזמן (שנה רביעית לתחום): אוטוקומפליט ואינטגרציה ב-IDE; Sonnet 3.5 כרגע-מודל מוקדם שבו הרבה עברו להשתמש תמיד; מצבים אג'נטיים בכלים (הרצת פקודות טרמינל, MCP)  -  רק לפני כשנה וחצי; טביעת המונח vibe coding של קרפתי' שהחזירה גל של משתמשים; סוכני רקע (Codex בענן, Claude Code בן כשנה); המונח context engineering תופס תאוצה; רגע ה-Opus; סקילס; ותחילת השנה  -  ניסויי ענק בנחילים (Gastown, הניסויים של Cursor ו-Anthropic לבנות קומפיילר C בדפדפן, Cloud Flow) שבהם סוכנים מחליטים כמה סוכנים צריך. ועכשיו? \"הנדסת רתמה\" הוא הבאזוורד, אבל בעיקר כולם עסוקים בעיכול ובשימוש בפועל  -  היא רואה את זה גם בקפיצות הפעילות בקהילת ה-AI הפנימית של ThoughtWorks.","points":["ציר: אוטוקומפליט → Sonnet 3.5 → מצבים אג'נטיים+MCP → vibe coding → סוכני רקע → context engineering → Opus → סקילס → נחילים","היום: עיבוד ושימוש בפועל, בלי באזוורד חדש; נחילים עדיין ניסיוניים"],"kind":"idea"},{"title":"העלויות המשניות: אבטחה, יציבות, שינוּי־יוּכולת, טוקנים ועומס קוגניטיבי","body":"התקדמנו הרבה  -  והעלויות גם, ולא רק טוקנים. אבטחה: דליפת סודות מהסביבות והאקוסיסטם תחת מתקפה; צריך יותר ניהול תלויות וסנדבוקסינג (וגם: הרצאה אתמול של ג'וסף מ-GitHub על AI שמשפר אבטחה). יציבות: דו\"ח DORA מצא לפי הדוברת החמרה ביציבות  -  ממצא שלילי בולט  -  אם כי יש גם הרצאות על AI שמשפר יציבות. שינוּי־יוּכולת (changeability): היא החדירה שינוי בקודבסיס חדש שנכתב כולו ב-AI, והוא נגע ב-41 קבצים  -  בלי צורך אמיתי; ריח ברור של חוב טכני מצטבר שמייקר שינויים. עלות טוקנים: בתחילת 2024 אמרו בהרצאה \"100 שורות קוד עולות 12 סנט\"  -  והיום ציטוטים ב-Pragmatic Engineer על מפתחים שמוציאים $500 ביום, יותר ממשכורת שנתית מכובדת (והיא מזכירה: שורות קוד הן לא מדד ערך). עומס קוגניטיבי ושריפה: אנשים עובדים יותר למרות שמייצרים יותר; סטיב ייגה השווה לערפד האנרגיה מ-What We Do in the Shadows  -  סיפורים על \"שלוש שעות ואז אני חייב תנומה\".","points":["אבטחה: דליפת סודות + אקוסיסטם תחת מתקפה","DORA: יציבות מחמירה (לדבריה); changeability: שינוי שגע ב-41 קבצים בלי סיבה  -  חוב טכני","טוקנים: מ-12 סנט ל-100 שורות ל-$500 ליום (ציטוטים מהעיתונות)","עומס קוגניטיבי: 'ערפד אנרגיה'  -  עובדים יותר, שרופים יותר"],"kind":"idea"},{"title":"משבר הריוויו, ואולי משבר זרימה","body":"אם כותבים קוד מהר יותר  -  האם סוקרים מהר יותר? בודקים? שולחים? עד כה התשובה הכללית היא לא, וכולם מתלוננים. וזה לא רק קוד: היא מספרת על ארגון שבו מנהלי מוצר זרמו פרוטוטייפים ורעיונות עם AI  -  ונוצר צוואר בקבוק מוזר בין ערימת הפרוטוטייפים לערימת הקוד, כי אף אחד לא יכול לסנכרן מה באמת בונים. האם אנחנו בדרך למשבר זרימה כללי? היא מפנה לעמיתה ג'יימס לואיס ולהרצאותיו על congestion collapse (יש לו לדבריה הימור על ארגז בירה עם ג'ין קים שזה יקרה): עומס יתר בסילואים שונים שהכול מאט עד קריסה  -  בהשראת תורת האילוצים והספר של דון ריינרטסן על product development flow.","points":["משבר הריוויו: תפוקת קוד עלתה, יכולת הביקורת לא","סילואים מואצים (פרוטוטייפים מול קוד) יוצרים צווארי בקבוק חדשים","תחזית 'congestion collapse' של ג'יימס לואיס  -  עומס יתר שמאט עד קריסה"],"kind":"idea"},{"title":"כמה פיקוח? הערכת סיכון: הסתברות, אימפקט, יכולת זיהוי","body":"השאלה הגדולה היא אמון בקוד וכמות הפיקוח  -  והתשובה תמיד \"תלוי\". אוטונומיית סוכני הקידוד כבר כאן, רק מחולקת לא שווה. המסגרת שלה היא הערכת סיכון קלאסית: הסתברות שה-AI יטעה (תלוי בידע שלך בכלי, בקונטקסט שנתת, ובביטחון שלך בדרישות בכלל); אימפקט אם יטעה (קריטיות של הזרימה העסקית  -  האם זה יעיר אותך בשתיים בלילה בשבת?); ויכולת זיהוי  -  האם אשים לב שמשהו השתבש (וזה מתחיל מלדעת מה זה \"נכון\"). לפי אלה בוחרים זרימת עבודה, כמות ריוויו, וכמה זמן משאירים בלי פיקוח. אפשר גם להגדיל את ההסתברויות לטובתך: הנדסת קונטקסט ורתמה טובות יותר, וריפקטורינג  -  AI מצליח הרבה יותר בקודבסיס מסודר. כמו שלט בלונה פארק: צריך להיות בגובה הזה כדי לצמצם פיקוח.","points":["אוטונומיה מחולקת לא שווה; 'כמה פיקוח' תלוי בסיכון","מסגרת: הסתברות × אימפקט × יכולת זיהוי (וקודם לדעת מה 'נכון')","מגדילים סיכויי הצלחה: קונטקסט/רתמה טובים + קודבסיס מסודר"],"kind":"idea"},{"title":"כניעה קוגניטיבית: במה אנחנו מוותרים?","body":"היא מזהירה ממגנט שמושך אותנו מ-in the loop ל-on the loop ל-out of the loop  -  והעלויות כבר מורגשות: עומס קוגניטיבי, חוב קוגניטיבי (לא מבינים איך הקודבסיס בנוי), דחייה קוגניטיבית (דוחים את העיבוד לאחרים), והמונח החדש \"כניעה קוגניטיבית\" (ממאמר שעדי עוסמני כתב עליו): החלפת חשיבת מערכת-2 ב-AI. דוגמאות לכניעות יומיומיות: \"יותר מדי מסובך להסביר  -  אעשה בעצמי\" (ואיך ג'וניורים ילמדו?); \"פשוט אשתמש במודל הכי גדול ויקר\"; \"המודלים ישתפרו והטוקנים יוזלו  -  רק לחכות\"; \"אין לי זמן למצוא גישות טובות יותר\" (לא תמיד אשמת הפרט  -  גם תמריצים); \"סנדבוקסינג זה מייגע, בטח כלום לא יקרה\"; \"אני כבר לא מסוגל לעבוד בקודבסיס בלי AI\". מול כולם: יש הרבה אפשרויות בין \"בלי AI בכלל\" לכניעה מוחלטת. מי שבעל השפעה  -  שיבנה סביבה שלא דוחפת לכניעה; מי שמרגיש חסר-אונים  -  שימצא את תחום ההשפעה הקטן שלו וישתף פעולה עם מי שטוב בתקשורת. ולסיכום הכישורים: להכיר את ארגז הכלים (ישן וחדש  -  גם לגלות מחדש דברים), חשיבה ביקורתית והערכת סיכון, סבלנות (פרודוקטיביות היא לא הקלדה), ולהנהגה: זה עדיין horizon 2  -  לתת לאנשים זמן לבנות סביבה טובה כדי לספק תוכנה בצורה בטוחה, מהירה ובת-קיימא.","points":["המגנט: in the loop → on the loop → out of the loop; העלויות כבר מורגשות","\"כניעה קוגניטיבית\" (עד' עוסמני): החלפת חשיבת מערכת-2 ב-AI  -  ויש עוד הרבה כניעות","יש טווח רחב בין 'בלי AI' לכניעה מוחלטת; מנהיגות: לבנות סביבה שלא דוחפת לכניעה","כישורים: ארגז כלים ישן+חדש, חשיבה ביקורתית, סבלנות; להנהגה  -  זה horizon 2"],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["שלושה דברים להכיר: יכולות המודל הבסיסיות, הבדלי הרתמות מתחת למכסה, ובעיקר  -  הנדסת קונטקסט: מדריכים וחיישנים שמגדילים סיכוי להצלחה.","12 החודשים האחרונים: מאוטוקומפליט דרך vibe coding לסוכני רקע ונחילים; היום בעיקר עיכול של הכול בפועל.","העלויות מסדר שני אמיתיות: אבטחה, יציבות, שינוּי־יוּכולת, טוקנים, עומס קוגניטיבי ומשבר ריוויו/זרימה.","פיקוח הוא הערכת סיכון (הסתברות×אימפקט×זיהוי), והמלכודת הגדולה היא כניעה קוגניטיבית  -  יש טווח רחב בין 'בלי AI' לכניעה מוחלטת."],"kind":"idea"}],"diagram":{"title":"המסגרת של בוקלר: מודל → רתמה מורחבת (מדריכים וחיישנים) → הערכת סיכון לפיקוח","structure":"שלוש שכבות מרכזיות: המודל בבסיס; מעליו הרתמה המורחבת  -  מצד אחד מדריכים (feed forward) ומצד שני חיישנים (feedback), כל אחד מחולק לאינפרנציאלי/חישובי, עם מיקומים לאורך הצנרת (pre-commit → PR → CI → 'איסוף זבל' שבועי → פרודקשן); ומסביב משולש הערכת הסיכון (הסתברות/אימפקט/זיהוי) שמכתיב כמה פיקוח אנושי נדרש, תחת איום ה'כניעה הקוגניטיבית'.","nodes":[{"id":"model","label":"המודל: לא קסם, חסר מצב, קונטקסט מול קשב, התאמה למשימה"},{"id":"guides","label":"מדריכים (feed forward): קונבנציות, קונטקסט מוצר, הוראות, code mods"},{"id":"sensors","label":"חיישנים (feedback): ריוויו LLM (אינפרנציאלי) / סטטי-לוגים-דפדפן (חישובי)"},{"id":"pipeline","label":"מיקום חיישנים: pre-commit → PR → CI → איסוף זבל שבועי → פרודקשן"},{"id":"risk","label":"הערכת סיכון לפיקוח: הסתברות × אימפקט × יכולת זיהוי"},{"id":"surrender","label":"האיום: עומס/חוב/דחייה/כניעה קוגניטיבית"}],"edges":[{"from":"guides","to":"model","label":"מגדיל סיכוי להצלחה ראשונה"},{"from":"sensors","to":"model","label":"תיקון עצמי לפני ריוויו אנושי"},{"from":"pipeline","to":"sensors","label":"איפה ומתי מפעילים כל חיישן"},{"from":"risk","to":"model","label":"כמה אוטונומיה להרשות"},{"from":"surrender","to":"risk","label":"שוחק את היכולת להעריך"}]},"terms":[{"term":"חוסר מצב (Statelessness)","definition":"למודל אין סשן; הרתמה שולחת את כל ההיסטוריה בכל תור (עם קאשינג)  -  עולה בחשיבות ככל שהשיחה מתארכת."},{"term":"קשב (Attention)","definition":"יכולת המודל לעקוב אחרי כל ההוראות והקונטקסט; יש טרייד-אוף מול גודל חלון הקונטקסט."},{"term":"רתמה (Coding harness)","definition":"התוכנה סביב המודל שמפעילה אותו לקידוד: פרומפטים, כלים, אורקסטרציה, ממשק, הרחבות ותצפיתיות."},{"term":"מדריך (Guide)","definition":"קונטקסט בפיד-פורוורד: קונבנציות, קונטקסט מוצרי, הוראות  -  שמגדיל את הסיכוי שהסוכן יצליח בפעם הראשונה."},{"term":"חיישן (Sensor)","definition":"משוב אוטומטי לסוכן: ריוויו אינפרנציאלי (LLM שופט LLM) או חישובי (ניתוח סטטי, לוגים) לתיקון עצמי."},{"term":"Code mods","definition":"כלי טרנספורמציה חישוביים (כמו OpenRewrite) לשדרוגים ומיגרציות; חזקים במיוחד בשילוב AI."},{"term":"איסוף זבל (Garbage collection)","definition":"זיהוי סחף רציף של חוב טכני שנצבר  -  סקירות תקופתיות (מודולריות, תלויות, אבטחה) עם תהליך טיפול צוותי."},{"term":"נחילים (Swarms)","definition":"שיגור המוני סוכנים (ולפעמים הסוכנים מחליטים כמה צריך) לבניית דברים גדולים אוטונומית  -  בשלב ניסיוני."},{"term":"שינוּי־יוּכולת (Changeability)","definition":"איכות קוד שנמדדת ביכולת לשנות אותו בקלות ובסיכון נמוך; קוד AI עלול לצבור חוב שמקשה שינוי."},{"term":"ערפד אנרגיה","definition":"האנלוגיה של סטיב ייגה לעומס הקוגניטיבי של עבודה עם AI: שואב אנרגיה עד שחייבים הפסקה."},{"term":"Congestion collapse","definition":"מצב שבו עומס יתר בצווארי בקבוק גורם להאטה קיצונית וקריסת זרימה; תחזית של ג'יימס לואיס לתחום ה-AI."},{"term":"יכולת זיהוי (Detectability)","definition":"הסיכוי שתשימו לב שה-AI טעה  -  רכיב בהחלטה כמה פיקוח נדרש."},{"term":"כניעה קוגניטיבית (Cognitive surrender)","definition":"מצב שבו מחליפים את החשיבה הפעילה (מערכת 2) ב-AI; מונח ממאמר שעדי עוסמני כתב עליו."},{"term":"Horizon 2","definition":"מסגרת ניהולית: עבודה על הדבר הבא שעוד לא בשל ל-ROI מלא  -  לדבריה, כך צריך להתייחס לאימוץ AI."}],"gaps":["ההרצאה מסתיימת ב'תודה' ובמחיאות כפיים  -  אין מקטע שאלות מתועד בתמלול המשוחזר (התמלול הרשמי נקטע מוקדם עוד יותר, באמצע משפט בשורה 155, והכתוביות המשוחזרות הן המקור המלא). ציטוטים ל-DORA, ל-Pragmatic Engineer, לסטיב ייגה, לג'יימס לואיס ולעדי עוסמני מובאים כדברי הדוברת ולא אומתו מקור חיצוני; שמות מודלים (Qwen 3.6, Gemma 4) כפי שנשמעו בתמלול."],"source_refs":["https://www.youtube.com/watch?v=tFffUnSq7VA"]},{"number":7,"id":"NVzKtCSeoRA","url":"https://www.youtube.com/watch?v=NVzKtCSeoRA","type":"session","type_he":"סשן","duration":"31:35 דקות","title_he":"הנדסה בעזרת סוכנים: מקרה בוחן מ-Meta","speaker_he":"איאן תומס · Meta","summary":"איאן מתאר איך בצוותי Horizon ב-Meta אימוץ כלי AI התרחב: קוד Hack ענק במאגר אחד (כ-500 מיליון שורות), מודל בגרות בשישה ממדים עם סדנה בסגנון קייזן, יוזמת anti-test-slop שאומצה בכל החברה, ודוגמאות מעשיות.","takeaways":["מודל בגרות עם שישה ממדים וסדנאות הערכה עצמית.","anti-test-slop: מניעת בדיקות חסרות ערך שנוצרו ב-AI.","תעדוף כיסוי: כ-3 שעות במקום חצי שבוע, כ-60 diffs.","ריפקטורינג בסוכנים מקבילים, גשר MCP ל-Horizon, וסוכני code mod.","דירוג סיכון של שינויים (בתמלול 'Confucius' ו-'Doctor').","מדדי 'ויניטי' מוכיחים שימוש ולא ערך."],"category":"מוצר וארגון","coverage":"כל התמליל הזמין נסקר. התמלול נחתך באמצע מילה בהודיה האחרונה.","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"איאן מתאר איך בצוותי Horizon ב-Meta אימוץ כלי AI התרחב: קוד Hack ענק במאגר אחד (כ-500 מיליון שורות), מודל בגרות בשישה ממדים עם סדנה בסגנון קייזן, יוזמת anti-test-slop שאומצה בכל החברה, ודוגמאות מעשיות.","chapters":[{"title":"פתיחה: מסע של שנה ב-Horizon Experiences","body":"איאן תומאס ממטא מספר סיפור מקרה מ-Horizon Experiences (חלק מ-Reality Labs): ב-12 חודשים עברו משימוש התחלתי ואד-הוק בכלי AI לשימוש הוליסטי בין צוותים ותהליכים, גם מחוץ להנדסה. הוא מתאר את נקודת ההתחלה: אנשים התחילו \"לגרור עקבים\" באימוץ. התוצאות שהוא מדווח לסוף התקופה: קהילה אורגנית שגדלה פי 40 ויותר (מעל 500 איש בתחילת השנה), שימוש שבועי שעלה מפחות מחצי למעל 80% (ולדבריו כיום באזור 95%+), זכיות זמן משמעותיות בזרימות מסוימות, ומודל בשלות שבנו והפיצו.","points":["קהילה אורגנית גדלה פי 40+ (500+ איש), שימוש שבועי מ-<50% ל-80%+ (לדבריו)","התחלה: אימוץ אד-הוק, תוצאות באיכות נמוכה, ידע בסילואים"],"kind":"idea"},{"title":"החזון והאתגר: להוריד טרחה מ-50% ל-5%","body":"החזון שההנהלה הציבה: להעביר מהנדסים מעבודה תפעולית וטרחה (undifferentiated heavy lifting) חזרה לחקר וחדשנות  -  לצמצם טרחה מכ-50% מזמן המהנדס לפחות מ-5%. נקודת הזינוק הייתה באמצע 2025 כשרוב העבודה עוד הייתה ידנית: עומס on-call, באגים. האתגר: אימוץ לא אחיד  -  אנשים השתמשו בכלים הלא נכונים לבעיות הלא נכונות, תהליכים לא אחידים, הצלחות נשארו בסילואים קטנים, ואנשים לא ראו החזר על הזמן שהשקיעו.","points":["חזון: טרחה מ-50% מזמן המהנדס ל-<5%","אתגר: אימוץ לא אחיד, כלים לא נכונים, ידע סילואי, תפיסת ערך נמוכה"],"kind":"idea"},{"title":"איפה מתחילים: מודרניזציה ומשימות אדמיניסטרטיביות בקודבסיס ענק","body":"הם בחרו בכוונה לא להתחיל בפיתוח פיצ'רים  -  תהליך חדש עם יותר מדי חלקים נעים  -  אלא במקום ששלטו בו: מודרניזציית קוד ומשימות אדמיניסטרטיביות, באגים ותקורה תפעולית. הסקייל: חצי מיליארד שורות Hack בריפו אחד (ואצוותה קטנה של Haskell בחצי מיליון שורות), כשהחלק שלו באמצע  -  תמהיל C++ ו-C# על פלטפורמת Unity. הנדסת מצוינות אצלם מורכבת משלושה חלקים: איכות מימוש, מצוינות ייצור (אינסידנטים, שירותים, באגים), ו\"הנדסה טובה יותר\" (כלים ותהליכים פנימיים).","points":["מתחילים בשטח מבוקר (מודרניזציה/אדמיניסטרציה), לא בפיתוח פיצ'רים","סקייל: ~500M שורות Hack בריפו אחד; VR מורכב (C++/C#, Unity)"],"kind":"idea"},{"title":"הקהילה: ground-up, מקום בטוח, החלטות מהירות","body":"במטא, חברה חברתית, דברים נעשים דרך משיכת אנשים למסע  -  לא צווים מלמעלה. תכנית \"הנדסת מצוינות\" הייתה המנוף: כבר היו בה קבוצות קטנות מוטיבציות. הם בנו קהילה קטנה שבה אנשים הרגישו בטוחים להיכשל ולשאול שאלות בלי פחד מביקורת ביצועים, עם פחות חיכוך והחלטות מהירות. מפה לאוזן הקהילה גדלה. הוא מדגיש היבט לא מדיד: תחושת שייכות ואמונה שזה ישתנה לתמיד  -  אין דשבורד ל\"שייכות\", וזו קפיצת אמון שצריך לבקש מהאנשים.","points":["אימוץ bottom-up דרך תכנית 'הנדסת מצוינות' הקיימת","מקום בטוח לכשלון ושאלות; החלטות מהירות בקבוצה קטנה","שייכות היא לא מדידה  -  ועדיין הקריטית"],"kind":"idea"},{"title":"מודל הבשלות: שישה מימדים, חמש רמות, סדנה לצוותים","body":"ממשוב הקהילה וממה שקרה בעולם סביב אוגוסט של אותה שנה, בנו מודל בשלות בהשראת מחקר DORA: שישה מימדים (למשל אינטגרציית זרימת עבודה, פרומפטינג, שיתוף פרומפטים, פרודוקטיביות אישית מול צוותית, מקרי שימוש מוצלחים מול מתקשים) על חמש רמות (אפס-אינדקס, \"כי אנחנו מהנדסים\"), כשהמימדים כמעט בלתי תלויים  -  אפשר להתקדם בכל אחד בנפרד. סביב המודל בנו סדנת הערכה עצמית: פשוטה בכוונה (פורמט קייזן-רטרו, הצבעה אנונימית ב-Miro, ואז דיון של 20-30 דקות שלפעמים התגלגל ל-45+), עם ריצה חוזרת כל 3-4 שבועות. הערך האמיתי: צוותים מוצאים את הפערים של עצמם ורואים התקדמות לאורך זמן  -  אחרת אין הוכחה שההשקעה משתלמת.","points":["מודל: 6 מימדים × 5 רמות (אפס-אינדקס), מימדים כמעט בלתי תלויים","סדנה: הצבעה אנונימית + דיון ארוך; ריצה חוזרת כל 3-4 שבועות","המעקב לאורך זמן הוא ההוכחה לערך  -  ומניע אימוץ"],"kind":"idea"},{"title":"מה יצא מהסדנאות: 'אפשר לסמוך על הקוד?' ויוזמת anti-test-slop","body":"כמעט מכל סדנה עלתה השאלה: האם אפשר לסמוך על הקוד? זו הייתה הסיבה העיקרית שהסניורים היססו  -  הם רצו שליטה ותחושת קרפט. זה כיוון את ההנהלה למאמצים חוצים: למשל בטסטים  -  AI היה מעולה בלהזות טסטים גרועים שנראים שימושיים אבל מעלים עומס CI  -  אז הושקה יוזמת anti-test-slop: כלי אוטונומי ב-CI שמעריך את איכות הטסטים שנוצרו (AI שופט AI). היוזמה שנולדה ב-Horizon אומצה על ידי אינפרה והופצה בכל החברה, ולדבריו עדיין רצה כמעט על כל דיף עם נפח טסטים מ-AI.","points":["השאלה החוזרת: 'אפשר לסמוך על הקוד?'  -  לב היסוס הסניורים","anti-test-slop: ביקורת AI אוטונומית על טסטים מ-AI ב-CI, הופצה לכל החברה"],"kind":"idea"},{"title":"ארבעה דפוסי הצלחה","body":"דפוס ראשון  -  כיסוי טסטים ממוקד: המהנדס בלראג' לימד סוכן לקרוא דשבורדים וטבלאות על קבצים לא מכוסים ועל שינויים חמים בהם, ובנה רשימת עדיפויות לכיסוי; לדבריו ב-3 שעות השיג מה שלוקח בערך חצי שבוע, ומהמאמץ נמזגו כמעט 60 דיפים. דפוס שני  -  ריפקטורינג מקבילי: ב-VR עובדים על מכונות Windows בודדות וחזקות, וריפקטורינגים מסוכנים נדחים; מהנדס לימד את ה-AI את דרך החשיבה שלו, מצא דפוסים חוזרים, ושיגר צוותי סוכנים במקביל בעוד הוא משמש סוקר ארכיטקטוני  -  חצי זמן. דפוס שלישי  -  שרת MCP כגשר לעולמות VR: במקום מכונת GPU ענקית למפתח, שרת שלימד את המודלים איך עולם Horizon בנוי (state, מודלים, טקסטורות) כדי שיעבדו בסביבות on-demand  -  הסרת מחסום ה-PC, מקביליות, ואיכות גבוהה יותר. דפוס רביעי  -  code mods אוטומטיים על תשתית החברה: כללים ו-runbooks כסקילס שגורמים לסוכנים למצוא בעיות, לתקן ולקדם דיפים; 30 דיפים אוטונומיים היו רק ההתחלה (לדבריו כיום הרבה יותר), ועוברים לריוויו לא-מפוקח בעיקר.","points":["כיסוי ממוקד: סוכן שקורא דאטה של כיסוי+חום קבצים → 60 דיפים (לדבריו)","ריפקטורינג מקבילי בצוותי סוכנים עם פיקוח ארכיטקטוני  -  חצי זמן","שרת MCP שמלמד את המודל את עולם ה-VR  -  בלי מכונת GPU פר-מפתח","code mods אוטומטיים: כללים כסקילס → דיפים שמקודמים לריוויו"],"kind":"idea"},{"title":"למה זה עבד: פוקוס, כלים משותפים, פיקוח, פלטפורמות","body":"מאחורי הזכיות: הגדרת בעיה ברורה (הנדסת מצוינות, לא ירי לכל כיוון), כלים משותפים שמיטיבים עם כולם (הצלבת רעיונות), שמירה על פיקוח אנושי קודם  -  לא קפיצה לעולם לא-מפוקח  -  ואיטרציה ושיתוף כמו באג'ייל. נקודת היסוד: פלטפורמות. כל הכלים התחברו לפלטפורמות קיימות עם נקודות כניסה מהירות  -  ההשקעה בפלטפורמות עדיין משלמת דיבידנדים, ודווקא בעולם שבו AI מצמצם צורך באנשים, הפלטפורמות מאפשרות לעשות יותר ביחד. דוגמאות: Confucius, פלטפורמה לבניית סוכנים מותאמים (הוא בנה סוכנים לביקורת דיפים במעבר בין גרסאות מוצר), ו-doctors שרץ על כל דיף בחברה ונותן ציון סיכון  -  מאפשר לדחוף דיפים לא-מסוכנים לפרודקשן מהר.","points":["הצלחה = בעיה ברורה + כלים משותפים + פיקוח אנושי + איטרציה","פלטפורמות הן הבסיס שמאפשר סקייל  -  גם בעידן AI","Confucius לבניית סוכנים; doctors לציון סיכון לדיף"],"kind":"idea"},{"title":"מה עבד, מה פחות, ומה למדוד","body":"מה שעבד: להתחיל קטן (יותר שליטה ומהירות), להתחבר לתהליכים קיימים, קהילה מלמטה שמעניקה אמינות  -  ואז דחיפה מלמעלה כשיש מסה קריטית; לתת רשות להיכשל ולשתף; לבחור תחומים פחות מסוכנים (כלים פנימיים, טסטים). מה שעדיין ממתין להוכחה: מה זה אומר על ריוויו קוד, איך לא ליצור צווארי בקבוק חדשים (תורת האילוצים), ומה העלות ארוכת הטווח של קוד מהיר שלא מבינים. על מדדים: התחילו עם אובססיה למשתמשים שבועיים, דיפים ושורות קוד  -  אבל אלה מדדי יוהרה; גם שימוש בטוקנים רק מראה שימוש, לא ערך. איך מודדים פרודוקטיביות אמיתית  -  עדיין נושא פעיל. ומה שנפסל: לא רצו אוטונומיה מלאה עדיין  -  אלא בחירה אילו זרימות מתאימות לעבודה לא-מפוקחת. ההמלצה: מצאו כמה אנשים והתחילו, בלי רשות; חלמו בגדול, התחילו בקטן; הציבו מודל בשלות וסדנאות; מצאו זכיות מהירות.","points":["עבד: קטן → קהילה → דחיפה מלמעלה; רשות להיכשל; תחומים פחות מסוכנים","מדדי יוהרה (משתמשים, דיפים, טוקנים) ≠ ערך","לא אוטונומיה מלאה  -  בחירת זרימות מתאימות ללא-מפוקח"],"kind":"idea"},{"title":"מה נשאר מהסשן","body":[],"points":["אימוץ AI בארגון גדול עובד מלמטה: קהילה קטנה ובטוחה על בסיס תהליך קיים (הנדסת מצוינות), ואז דחיפה מלמעלה במסה קריטית.","מודל בשלות (6 מימדים × 5 רמות) עם סדנאות חוזרות הוא הדרך להפוך אימוץ למדיד ולהוכיח ערך לאורך זמן.","הדפוסים המנצחים: מיקוד בבעיה ברורה, כלים משותפים, פיקוח אנושי קודם, ובסיס פלטפורמות חזק.","מדדי שימוש הם יוהרה; השאלות הפתוחות: ריוויו, צווארי בקבוק חדשים, ועלות ארוכת טווח של קוד שלא מבינים."],"kind":"idea"}],"diagram":{"title":"המסלול של תומאס: קהילה קטנה → מודל בשלות → דפוסים → אפקט כדור שלג","structure":"לולאת צמיחה: מתחילים קטן בתחום מבוקר (מודרניזציה/טרחה) עם קהילה בטוחה → סדנאות מודל הבשלות (6 מימדים × 5 רמות) חושפות פערים → דפוסי הצלחה (טסטים, ריפקטורינג, MCP, code mods) → דחיפת הנהלה → אפקט כדור שלג; מעל הכול פלטפורמות כבסיס, ופיקוח אנושי כקו מנחה.","nodes":[{"id":"start","label":"התחלה קטנה: מודרניזציה/טרחה, קהילה בטוחה (ground-up)"},{"id":"model","label":"מודל בשלות: 6 מימדים × 5 רמות + סדנת הערכה עצמית"},{"id":"patterns","label":"דפוסים: כיסוי ממוקד, ריפקטורינג מקבילי, MCP, code mods, anti-test-slop"},{"id":"topdown","label":"דחיפת הנהלה + הפצה לארגון"},{"id":"snowball","label":"אפקט כדור שלג: ×40 קהילה, 80%+ שבועי"},{"id":"platforms","label":"בסיס: פלטפורמות (Confucius, doctors) + פיקוח אנושי"}],"edges":[{"from":"start","to":"model","label":"משוב → מסגרת מדידה"},{"from":"model","to":"patterns","label":"פערים → ניסויים ממוקדים"},{"from":"patterns","to":"topdown","label":"הוכחות ערך"},{"from":"topdown","to":"snowball","label":"מסה קריטית"},{"from":"platforms","to":"patterns","label":"סקייל מהיר"}]},"terms":[{"term":"טרחה (Toil)","definition":"עבודה תפעולית שאינה מבדלת (on-call, באגים, תחזוקה) שהחזון ביקש לצמצם מ-50% ל-5% מזמן המהנדס."},{"term":"מודל בשלות (Maturity model)","definition":"מסגרת של מימדים ורמות להערכה עצמית של צוות באימוץ AI, עם ריצה חוזרת למדידת התקדמות."},{"term":"Test slop","definition":"טסטים שנוצרו ב-AI ונראים שימושיים אבל חסרי ערך  -  מעלים עומס CI בלי כיסוי אמיתי."},{"term":"שרת MCP","definition":"גשר שנותן למודל את ההקשר של העולם (כאן: מבנה עולמות VR) כדי לעבוד בסביבות סטנדרטיות במקביל."},{"term":"מדדי יוהרה (Vanity metrics)","definition":"מדדי שימוש (משתמשים שבועיים, דיפים, טוקנים) שאינם מוכיחים ערך שנוצר."}],"gaps":["התמלול מסתיים בתודה ובמחיאות כפיים  -  אין מקטע שאלות מתועד. כל המספרים (×40 קהילה, 80%+, 60 דיפים, 3 שעות מול חצי שבוע, 30 דיפים אוטונומיים, ~500M שורות) מובאים כדברי הדובר ולא אומתו מקור חיצוני. שם הכלי 'Confucius' כפי שנשמע בתמלול האוטומטי."],"source_refs":["https://www.youtube.com/watch?v=NVzKtCSeoRA"]},{"number":8,"id":"xHxfeWtkXrM","url":"https://www.youtube.com/watch?v=xHxfeWtkXrM","type":"session","type_he":"סשן","duration":"32:04 דקות","title_he":"כשבדיקות משקרות: תצפית כדי לשמור על AI ישר","speaker_he":"ג׳סטין קורמק","summary":"ג'סטין בנה עם AI מערכת אחסון תואמת S3 ב-Rust (כ-350 אלף שורות), ומסביר מה נדרש כדי לסמוך עליה: אורקל בדיקות מול S3 אמיתי, שליטה בבדיקות פלאקי, תצפית ומסגרת tracing, בדיקות ביצועים, ושימוש בטיפוסים (AuthorizedRequest) להקשחת הרשאות.","takeaways":["אורקל: כ-1,500 בדיקות מול S3 אמיתי, כי התיעוד לא אמין.","כ-5,000 בדיקות ברצות בשתי דקות; בדיקות פלאקי מתוקנות מיד.","מסגרת tracing שנבנתה בבית, ובדיקות ביצועים.","Codex Security לסקירת אבטחה.","בשאלות: גם שאלה על אימות פורמלי."],"category":"אימות ואיכות","coverage":"כל התמליל הזמין נסקר. שאלות ותשובות נחתכו ('It's one right at the back').","source_basis":"תמלול ההרצאה הזמין, עם בדיקת התאמה למאגר הטקסט הרשמי כשקיים מקור מתאים. לא בוצעה צפייה בווידאו.","lead":"ג'סטין בנה עם AI מערכת אחסון תואמת S3 ב-Rust (כ-350 אלף שורות), ומסביר מה נדרש כדי לסמוך עליה: אורקל בדיקות מול S3 אמיתי, שליטה בבדיקות פלאקי, תצפית ומסגרת tracing, בדיקות ביצועים, ושימוש בטיפוסים (AuthorizedRequest) להקשחת הרשאות.","chapters":[{"title":"הפרויקט: לבנות מערכת אחסון S3-תואמת עם AI","body":"ג'סטין קורמק, חובב תשתיות ואחסון אובייקטים, רצה לבדוק אם אפשר לבנות מערכות ענק עם AI  -  אחרי ש-MinIO הפסיקו לתחזק את מוצר האחסון התואם-S3 שלהם. מימושים כאלה לוקחים שנתיים ואף עשור; הוא החליט לנסות בשבוע. התוצאה: 350 אלף שורות Rust  -  שפה שהוא רק חצי למד, וכן, הוא מודה שלא קרא את כל הקוד. הכללים שלו: להבין את הקוד באופן כללי ולהישאר בלולאה, דעות ארכיטקטוניות ברורות (לא לתת לזה לקרוס לכאוס אחרי 100 אלף שורות, כפי ששמע מאחרים), רקע באבטחה וביצועים, ולא לאוטמט הכול מראש  -  הוא רוצה לדעת מה השתבש, כי הוא אחראי לאיכות. והשאלה הגדולה: האם אפשר להיות שאפתניים ולבנות דברים שמעולם לא היינו מנסים?","points":["הניסוי: מערכת S3-תואמת ב-Rust; 350K שורות (מימושים כאלה לוקחים שנים)","כללים: להישאר בלולאה, דעות ארכיטקטוניות, לא לאוטמט מראש, אחריות אישית לאיכות"],"kind":"idea"},{"title":"מגבלות הטסטים: כיסוי 100% הוא לא המטרה","body":"הוא פותח בציטוט מדמינג: אי אפשר לבדוק איכות לתוך מוצר בדיעבד  -  בונים אותה תוך כדי. בפרויקטים קטנים עם AI אפשר לבדוק הכול בקפדנות, אבל במערכות גדולות זה משתבש. הוא שמע את הטענה \"עם AI צריך רק 100% כיסוי\"  -  וניסה: הבקשה היא לא מועילה, כי הסוכן כותב טסטים טריוויאליים כדי להשלים אחוזים, ומקרי שגיאה מוזרים (למשל \"מחולל המספרים האקראי נכשל\") פשוט לא שווים בדיקה. בפועל יש לו 75%-100% כיסוי לקובץ  -  הרבה טסטים בלי אובססיית המאה. וחשוב: יש דברים שטסטים לא יכולים למצוא בכלל  -  בעיות אבטחה, איכות ארכיטקטורה, וכל דבר שאי אפשר למדוד. מי שמתמקד רק בכיסוי לא חושב על אבטחה מספיק.","points":["100% כיסוי מייצר טסטים טריוויאליים ולא שופך אור על מקרי קצה אמיתיים","75-100% לקובץ עם טסטים משמעותיים > אובססיית מאה אחוז","טסטים לא מוצאים אבטחה וארכיטקטורה  -  צריך כלים נוספים"],"kind":"idea"},{"title":"אורקל מבחנים: להעתיק מערכת קיימת ולא לסמוך על תיעוד","body":"הכלי המרכזי הוא אורקל מבחנים: S3 עצמה. הוא מריץ טסטים ישירות מול AWS ואומר ל-AI \"עשה בדיוק ככה\"  -  זה נותן בסיס מצוין. לקח נלווה: אם בונים מערכת מורכבת חדשה, כדאי קודם לכתוב גרסה פשוטה וטריוויאלית עם אותה התנהגות ולבנות סוויטת טסטים נגדה  -  ואז לבנות את הגרסה המורכבת מולה. גילוי מפתיע: התיעוד של S3, מאות עמודים, מתברר כשגוי ברוב הפרטים  -  לעולם לא לסמוך על תיעוד; הטסטים מול ההתנהגות האמיתית הם מה שמעוגן. ועוד גבול: ה-API הציבורי לא חושף התנהגויות פנימיות (מתי פריט באמת נמחק)  -  צריך להסיק או לבדוק בעקיפין.","points":["אורקל = S3 עצמה; מריצים מולו ודורשים התאמה מדויקת","למערכת חדשה: קודם גרסה טריוויאלית כאורקל, אחר כך המורכבת","התיעוד של אמזון שגוי ברוב הפרטים (לדבריו)  -  ההתנהגות בפועל היא המקור","API ציבורי לא חושף התנהגות פנימית  -  צריך דרכים עקיפות"],"kind":"idea"},{"title":"מקרי קצה: למצוא באגים אצל אמזון","body":"מקרי הקצה הם ההוכחה שהסוויטה טובה: ה-AI כתב טסטים אקראיים מול S3 ומצא שגיאת 500 ניתנת לשחזור  -  כלומר לאמזון לא היה טסט לזה, ולו כן. זה נתן לו ביטחון שחקר חלק ניכר ממרחב הבדיקות (מאוחר יותר נמצאה עוד שגיאת 500). מי מוצא קצוות? הוא מוצא אותם בקריאת תיעוד ובשאלה \"האם זה באמת נכון?\"; לעומתו, כשהוא שלח את ה-AI לתיעוד לחפש קצוות  -  הוא היה גרוע בזה. דרך הטסטים עצמם: שאלות קלאסיות כמו אורכים אפס/אחד/10,001 עוזרות, אבל צריך לחשוב כמו בודק ולשער איפה מסתתרות שגיאות.","points":["ה-AI מצא שגיאות 500 ניתנות לשחזור ב-S3 עצמה  -  הוכחת עומק הסוויטה","אדם מוצא קצוות בתיעוד טוב יותר מה-AI; טסטים אקראיים ו-property עוזרים"],"kind":"idea"},{"title":"טסטים רעננים: כלל ברזל וריצות לילה","body":"AWS \"מתכנסת לאמת לאורך זמן\" (eventual consistency), וזה גרם לטסטים רעננים שבזבזו המון זמן  -  למשל הרשאות שלא תקפות מיד. הכלל שלו: אף פעם לא טסטים רעננים עם AI  -  מתקנים מיד. הבעיה: דאטת האימון אומרת שמתכנתים אף פעם לא מתקנים טסטים רעננים, אז הסוכן מתעלם מהם; הוא צועק עליו \"אצלנו מתקנים  -  כתוב ב-AGENTS.md\". ולפעמים הסוכן מחליט שאמזון שינתה התנהגות ומשנה את הקוד להתאים  -  ואז היא משתנה בחזרה. בנוסף: טסטים מהירים שרצים הרבה  -  לו יש 5,000 טסטים בדקתיים, שזה הגבול שלו  -  וריצות לילה חוזרות על מכונות מרובות כדי לתפוס תקלות נדירות.","points":["כלל ברזל: מתקנים טסטים רעננים מיד; דאטת האימון מלמדת סוכנים להתעלם מהם","5,000 טסטים בדקתיים, ריצות לילה על מכונות מרובות לתפיסת תקלות נדירות"],"kind":"idea"},{"title":"סוגי טסטים ותצפיתיות: לתת ל-AI כלים לדבוג","body":"הוא ממליץ להרחיב את מגוון הבדיקות: מדי פעם הוא שואל את הסוכן \"אילו טסטים היינו צריכים כדי לתפוס את הבעיות האלה?\"  -  וכך נולדו fuzzing ו-property-based testing שמצאו בעיות אמיתיות. וכדי להפוך דברים לבדיקים: כל אות שיוצאת מהקופסה השחורה היא מידע  -  הוא מצטער שלא בנה ממשקי ניהול ודיווח פנימיים מוקדם יותר כדי לבדוק דרכם. טרייסינג: הוא גילה ששווה לגרום ל-AI לבנות פריימוורק טרייסינג ידני ומתוחזק  -  גם בלי חיבור לפרודקשן. אם נותנים לסוכן באג נדיר בלי שחזור, הוא עלול לנחש ולטעות; אם נותנים לו טרייס וכלי טרייסינג ומבקשים לשחזר בעצמו  -  בדרך כלל הוא מצליח לנעול את הבעיה האמיתית. הטרייסינג אמנם מטעה קצת במדידות ביצועים בגלל התקורה, אבל חשף את הפערים הגדולים.","points":["לשאול את הסוכן 'אילו טסטים היו תופסים את זה?' → fuzzing ו-property tests","לבנות ממשקי ניהול פנימיים כדי להפוך את הבלתי-נראה לבדיק","טרייסינג עצמי = כלי הדיבוג של הסוכן: באג נדיר + טרייס → שחזור ותיקון"],"kind":"idea"},{"title":"ביצועים ואבטחה: מה שטסטים לא פותרים","body":"בביצועים ה-AI התנהג כמו בני אדם: מבצע שינוי שלא משפר או אפילו מחמיר, כי \"נראה הגיוני\". הלקח: לקבל שזו עבודה זולה ולזרוק מה שלא עובד. בהשוואה למימוש S3 אחר הגיע לקריאות זהות, אבל הכתיבות היו איטיות  -  עד שהסוכן מצא הערה בקוד שלהם: הם לא עושים fsync. אם הם לא מסנכרנים, ברור שזה מהיר יותר  -  ואין טעם להשתוות למשהו שלא רוצים לעשות. באבטחה: בעיות הרשאות מסוג time-of-check-time-of-use הוא ניסה לתפוס בטרייסינג, ובסוף פתר דרך מערכת הטיפוסים  -  טיפוס \"בקשה מורשית\" שאי אפשר לעקוף, כך שכל פונקציה בשער מקבלת רק בקשות מורשות. כשהטיפוסים אוכפים  -  לא צריך טסט. בנוסף הוא מריץ סקירות אבטחה של Codex: הוא משקף את הממצאים לריפו ומבקש מה-AI לסקור אותם; לדבריו כשלושה רבעים תקפים  -  חלקם חשובים וגדולים  -  ובנוסף עושה מדי פעם סקירת מצב מלאה של הקוד (לא רק PRs).","points":["ביצועים: לזרוק שינויים שלא עובדים; אין טעם להשתוות למערכת בלי fsync","TOCTOU: לפתור בטיפוסים ('בקשה מורשית') במקום בטסטים","סקירות אבטחה AI: ~3/4 מהממצאים תקפים (לדבריו); גם סקירת מצב מלאה, לא רק PRs"],"kind":"idea"},{"title":"האדם בלולאה, ריפקטורינג, ומה למדנו","body":"הוא רואה את עצמו חלק ממעגל המשוב: יש לו דעות, הוא כאן כדי לגלות מה השתבש, והוא בכוונה לא מאוטמט יתר על המידה כי הוא אחראי לאיכות. גרף הקומיטים שלו מספר סיפור: היו שבועות ריפקטורינג מטורפים (120 אלף שורות פלוס, 75 אלף מינוס, קובץ בודד בן 43 אלף שורות)  -  ריפקטורינג הוא חלק מהמעגל החיצוני של העבודה; לא מנסים לעשות one-shot אלא מתכנסים לתשובה טובה יותר. טסטים הם כלי גילוי, לא תשובה סופית: מרחיבים אותם לפי אי-ודאות וחשד, ותפקידך הוא לשבור דברים ולתקן. לקחים: אורקל/מודל שימושי מאוד; להעתיק מערכת קיימת היא פעילות מצוינת עם היסטוריה מכובדת בקוד פתוח. הוא מתכוון לשחרר את הקוד בקוד פתוח תוך שבוע בערך. בשאלות: האם ניסה וריפיקציה פורמלית?  -  עוד לא; רוצה אחרי שהמערכת המבוזרת תרוץ, ויש דיווחים מעורבים כמה AI טוב בזה. ועל האתגר שאורקל חייב ליישם את אותה התנהגות בדרך שונה לגמרי כדי לא לקבל טאוטולוגיה: נכון  -  אצלו S3 חיצוני עוזר, ובפרויקט חדש הוא היה בונה את האורקל מחוץ לריפו כמודל קבוע.","points":["האדם חלק ממעגל המשוב: אחריות לאיכות, לא אוטומציה עיוורת","ריפקטורינג שבועי ענק הוא חלק מהתכנסות; טסטים = כלי גילוי","Q&A: וריפיקציה פורמלית בהמשך; אורקל חייב דרך שונה כדי לא להיות טאוטולוגיה"],"kind":"idea"},{"title":"האם ניסית וריפיקציה פורמלית לחלק המבוזר?","body":"עוד לא  -  בתכנון אחרי שתוכנית המעבר למבוזר תושלם; יש דיווחים מעורבים כמה AI טוב בזה, והוא סקרן לבדוק.","kind":"qa"},{"title":"איך מונעים שהאורקל יהיה טאוטולוגיה (אותו מימוש פעמיים)?","body":"קל יותר כשהאורקל חיצוני כמו S3; בפרויקט חדש הוא היה בונה אורקל קבוע מחוץ לריפו, כי אחרת מגלים שלא בודקים כלום.","kind":"qa"},{"title":"מה נשאר מהסשן","body":[],"points":["אפשר לבנות מערכות ענק עם AI  -  בתנאי שהאדם נשאר בלולאה עם אחריות לאיכות ודעות ארכיטקטוניות.","כיסוי 100% הוא לא המטרה; טסטים הם כלי גילוי שמרחיבים לפי חשד  -  ויש דברים שרק טרייסינג, טיפוסים וסקירות אבטחה מגלים.","אורקל מבחנים (מערכת קיימת או גרסה טריוויאלית) הוא הבסיס; תיעוד לא אמין  -  ההתנהגות בפועל היא האמת.","טסטים רעננים מתקנים מיד, טסטים מהירים מריצים הרבה, ובאגים נדירים פותרים עם טרייסים ולא ניחושים."],"kind":"idea"}],"diagram":{"title":"המעגל של קורמק: אורקל, טסטים, טרייסים, טיפוסים  -  והאדם ששובר","structure":"מעגל משוב סביב 'המערכת': האורקל (S3) מייצר ציפיות; סוגי טסטים שונים בודקים; טרייסינג חושף בלתי-נראה; מערכת הטיפוסים אוכפת הרשאות; סקירות אבטחה AI מכסות את מה שטסטים לא רואים; והאדם בלולאה מחליט איפה לחשוד, מרחיב בדיקות, ומוביל ריפקטורינג.","nodes":[{"id":"oracle","label":"אורקל: S3 האמיתית (וגרסה טריוויאלית למערכת חדשה)"},{"id":"tests","label":"טסטים: רגילים, fuzz, property, ביצועים  -  מהירים ובלי רעננים"},{"id":"tracing","label":"טרייסינג עצמי: לשחזר באגים נדירים"},{"id":"types","label":"מערכת טיפוסים: אכיפת הרשאות בלי טסטים"},{"id":"secrev","label":"סקירות אבטחה AI + סקירת מצב מלאה"},{"id":"human","label":"האדם בלולאה: חושד, שובר, מרחיב, מרפקטר"}],"edges":[{"from":"oracle","to":"tests","label":"התנהגות נכונה להשוואה"},{"from":"tests","to":"tracing","label":"כישלון נדיר → שחזור"},{"from":"types","to":"tests","label":"מה שאוכפים לא בודקים"},{"from":"secrev","to":"tests","label":"ממצאים → טסטים חדשים"},{"from":"human","to":"tests","label":"מרחיב לפי חשד"},{"from":"human","to":"oracle","label":"קצוות מהתיעוד"}]},"terms":[{"term":"אורקל מבחנים (Test oracle)","definition":"מערכת ייחוס שמתנהגת נכון (כאן: S3 עצמו) שאליה משווים תוצאות  -  הבסיס לכל הבדיקות."},{"term":"טסט רענן (Flaky test)","definition":"טסט שלפעמים עובר ולפעמים נכשל בלי שינוי קוד; הכלל שלו  -  לתקן מיד, לא להתעלם."},{"term":"Property-based testing","definition":"בדיקות שמייצרות מקרים אקראיים מול תכונות שצריכות להתקיים תמיד; מצא בעיות אמיתיות."},{"term":"TOCTOU","definition":"Time-of-check-time-of-use: בעיית הרשאות שבה הבדיקה והשימוש מתרחשים בזמנים שונים; נפתרה בטיפוסים."}],"gaps":["השאלות הסתיימו על ידי המנחה (\"נגמר הזמן\") אחרי שתי שאלות. הנתונים (350K שורות, 5,000 טסטים בדקתיים, 75-100% כיסוי, ~3/4 ממצאי אבטחה תקפים) מובאים כדברי הדובר ולא אומתו מקור חיצוני. הדובר מתכוון לפתוח את הקוד בעתיד  -  טרם נבדק שאירע. במאגר הרשמי התיקייה talk-roberts-ai-native-brownfield מתויגת בטעות; זו הרצאתו של קורמק."],"source_refs":["https://www.youtube.com/watch?v=xHxfeWtkXrM"]}]);
